&quot;, &quot;。&quot;, &quot;！&quot;, &quot;？&quot;, &quot;；&quot;, &quot;，&quot;, &quot; &quot;, &quot;&quot;] ) # 4. 连接到 Milvus self._connect_to_milvus() 文档处理流水线12345678910111213141516def process_file(self, file_path: str, collection_name: str = None) -&gt; bool: &quot;&quot;&quot;处理单个文件：加载 → 切分 → 存储&quot;&quot;&quot; # 步骤1: 加载文档 documents = self.load_document(file_path) # 例如: PDF 文件会被解析为多个 Document 对象 # 步骤2: 切分文档 split_docs = self.split_documents(documents) # 将长文档切分为多个小块 # 步骤3: 存入向量数据库 self.add_documents_to_db(split_docs, collection_name) # 自动调用嵌入模型，生成向量并存储 return True 向量存储逻辑12345678910111213141516171819202122def add_documents_to_db(self, documents: List[Document], collection_name: str = None): &quot;&quot;&quot;将文档添加到 Milvus&quot;&quot;&quot; target_collection = collection_name or self.collection_name collection_exists = utility.has_collection(target_collection) if collection_exists: # 集合已存在：加载并追加数据 self.vectorstore = Milvus( embedding_function=self.embeddings, collection_name=target_collection, connection_args=&#123;&quot;host&quot;: self.milvus_host, &quot;port&quot;: self.milvus_port&#125; ) self.vectorstore.add_documents(documents) # 追加 else: # 集合不存在：创建新集合并插入 self.vectorstore = Milvus.from_documents( documents=documents, embedding=self.embeddings, collection_name=target_collection, connection_args=&#123;&quot;host&quot;: self.milvus_host, &quot;port&quot;: self.milvus_port&#125; ) 6.2 向量检索器 (vector_retriever.py)这个模块负责 RAG 的”读取”流程。 相似度搜索1234567891011121314151617def search_similar_content(self, query: str, collection_name: str, k: int = None): &quot;&quot;&quot;搜索相似内容&quot;&quot;&quot; # 执行向量搜索（内部会自动将 query 转为向量） search_results = self.db_manager.search( query=query, k=k, collection_name=collection_name ) # 过滤低相似度结果 results = [] for doc, score in search_results: if score &gt;= self.similarity_threshold: # 默认 0.5 results.append((doc, score)) return results 问答生成123456789101112131415161718192021222324def answer_question(self, question: str, collection_name: str, k: int = 5): &quot;&quot;&quot;回答问题 - RAG 的核心逻辑&quot;&quot;&quot; # 步骤1: 检索相关文档 relevant_docs = self.search_similar_content( query=question, collection_name=collection_name, k=k ) # 步骤2: 构建上下文 context_parts = [] for i, (doc, score) in enumerate(relevant_docs): context_parts.append(f&quot;参考资料&#123;i+1&#125;: &#123;doc.page_content&#125;&quot;) context = &quot;

&quot;.join(context_parts) # 步骤3: 调用 LLM 生成回答 answer = self._generate_answer_with_llm(question, context) return AnswerResult( answer=answer, source_documents=source_documents, scores=scores ) LLM 调用1234567891011121314151617181920def _generate_answer_with_llm(self, question: str, context: str) -&gt; str: &quot;&quot;&quot;使用 LLM 生成回答&quot;&quot;&quot; client = OpenAI( api_key=os.environ.get(&quot;DASHSCOPE_API_KEY&quot;), base_url=&quot;https://dashscope.aliyuncs.com/compatible-mode/v1&quot; ) system_prompt = &quot;&quot;&quot;你是一个智能助手。请基于提供的【参考资料】回答用户的问题。 如果参考资料为空或与问题无关，请利用你的通用知识进行回答...&quot;&quot;&quot; response = client.chat.completions.create( model=&quot;qwen-plus&quot;, messages=[ &#123;&quot;role&quot;: &quot;system&quot;, &quot;content&quot;: system_prompt&#125;, &#123;&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: f&quot;问题：&#123;question&#125;

