&#123;context&#125;&quot;&#125; ] ) return response.choices[0].message.content 6.3 API 接口 (api_integration.py)提供 REST API 供外部调用。 上传文档端点1234567891011121314151617@vector_bp.route(&#x27;/upload_document&#x27;, methods=[&#x27;POST&#x27;])def upload_document(): &quot;&quot;&quot;POST /api/vector/upload_document&quot;&quot;&quot; data = request.get_json() file_path = data[&#x27;file_path&#x27;] collection_name = data[&#x27;collection_name&#x27;] # 调用核心处理逻辑 success = vector_manager.process_file(file_path, collection_name) if success: return jsonify(&#123; &#x27;success&#x27;: True, &#x27;message&#x27;: f&#x27;文档处理成功: &#123;file_path&#125;&#x27;, &#x27;database_info&#x27;: vector_manager.get_database_info(collection_name) &#125;) 查询端点1234567891011121314151617181920212223@vector_bp.route(&#x27;/query&#x27;, methods=[&#x27;POST&#x27;])def query_documents(): &quot;&quot;&quot;POST /api/vector/query&quot;&quot;&quot; data = request.get_json() question = data[&#x27;question&#x27;] collection_name = data[&#x27;collection_name&#x27;] k = data.get(&#x27;k&#x27;, 5) # 执行 RAG 问答 result = vector_retriever.answer_question( question, k=k, collection_name=collection_name ) return jsonify(&#123; &#x27;success&#x27;: True, &#x27;question&#x27;: question, &#x27;answer&#x27;: result.answer, &#x27;confidence&#x27;: result.confidence, &#x27;sources&#x27;: [...] # 来源文档信息 &#125;) 快速上手指南 7.1 环境准备 启动 Milvus（使用 Docker） 12# 创建 docker-compose.yml 并启动docker-compose up -d 安装 Python 依赖 1234pip install langchain langchain-community langchain-milvuspip install pymilvus dashscope openaipip install flask flask-cors python-dotenvpip install pypdf docx2txt pandas openpyxl 配置环境变量 创建 .env 文件： 123456MILVUS_HOST&#x3D;localhostMILVUS_PORT&#x3D;19530COLLECTION_NAME&#x3D;agent_ragDASHSCOPE_API_KEY&#x3D;your_api_key_hereEMBEDDING_MODEL&#x3D;text-embedding-v1LLM_MODEL&#x3D;qwen-plus 7.2 命令行使用上传文档： 12# 修改 upload_document.py 中的 FILE_PATHpython upload_document.py 查询问答： 12# 修改 query_system.py 中的 QUESTIONpython query_system.py 7.3 API 使用启动服务： 1python server.py 上传文档： 123curl -X POST http://localhost:5000/api/vector/upload_document \ -H &quot;Content-Type: application/json&quot; \ -d &#x27;&#123;&quot;file_path&quot;: &quot;/path/to/doc.pdf&quot;, &quot;collection_name&quot;: &quot;my_docs&quot;&#125;&#x27; 提问： 123curl -X POST http://localhost:5000/api/vector/query \ -H &quot;Content-Type: application/json&quot; \ -d &#x27;&#123;&quot;question&quot;: &quot;什么是RAG？&quot;, &quot;collection_name&quot;: &quot;my_docs&quot;, &quot;k&quot;: 5&#125;&#x27; API 接口说明 端点 方法 描述 /api/vector/upload_document POST 上传并处理文档（路径方式） /api/vector/upload_file POST 上传文件流 /api/vector/query POST RAG 问答 /api/vector/search POST 纯相似度搜索 /api/vector/collection_info GET 获取集合信息 /api/vector/clear_collection POST 清空集合

AI开发基础：Langgraph框架从入门到实战开发智能体-附带完整可运行代码 LangGraph 实战教程：从小白到高手 一份让你真正学会用 LangGraph 构建 AI Agent 的实战指南 写在前面如果你想用大语言模型（LLM）做点有意思的事情，比如做一个能自己查资料、能记住上下文、能调用各种工具的智能助手，那 LangGraph 绝对是你需要了解的东西。 这份教程不会堆砌一堆概念把你绕晕，而是用真实可运行的代码带你一步步搞懂这玩意儿到底怎么用。 直接可以运行的代码已经整理好了，需要的话找老师拿 第一章 LangGraph 是什么 一句话解释LangGraph 就是用来编排 AI 工作流的框架，让你可以把复杂的 AI 任务拆成一个个小步骤，然后像搭积木一样把它们连起来。 为什么需要它？假设你要做一个客服机器人： 先要判断用户问的是技术问题还是销售问题 技术问题交给技术 Agent 处理 销售问题交给销售 Agent 处理 如果答案质量不够好，还得循环改进 这种有分支、有循环、有状态的复杂流程，用普通代码写起来会很乱。LangGraph 就是专门解决这个问题的。 LangGraph vs LangChain很多人搞不清这俩的关系： 特性 LangChain LangGraph 定位 通用 LLM 工具库 工作流编排框架 流程 线性链条（A→B→C） 图结构（支持分支、循环） 状态 需要手动管理 自动管理 适合场景 简单的问答、RAG 复杂的 Agent、多步骤任务 简单说：LangChain 是做零件的，LangGraph 是用这些零件搭建复杂系统的。 第二章 环境准备安装依赖12345678# 核心依赖pip install langgraph langchain-core langchain-community# 如果要用通义千问pip install dashscope# 如果要用 OpenAIpip install langchain-openai 设置 API Key1234567import os# 通义千问os.environ[&quot;DASHSCOPE_API_KEY&quot;] = &quot;你的key&quot;# 或者 OpenAIos.environ[&quot;OPENAI_API_KEY&quot;] = &quot;你的key&quot; 第三章 核心概念LangGraph 就三个核心概念，搞懂了这三个，其他都是组合拳。 State（状态） State 就是一个在所有节点间共享的数据结构。你可以把它想象成一个”快递包裹”，每经过一个节点，就往里面加点东西或者修改点东西。 12345from typing_extensions import TypedDictclass MyState(TypedDict): count: int # 计数器 history: list[str] # 历史记录 Node（节点） Node 就是干活的。每个节点是一个 Python 函数，接收当前状态，返回需要更新的字段。 123456789def my_node(state: MyState): # 读取当前状态 current_count = state[&quot;count&quot;] # 返回要更新的字段（不用返回所有字段！） return &#123; &quot;count&quot;: current_count + 1, &quot;history&quot;: state[&quot;history&quot;] + [&quot;执行了一次&quot;] &#125; Edge（边） Edge 定义节点之间怎么连接，决定执行顺序。 123456789# 普通边：A 执行完必定执行 Bworkflow.add_edge(&quot;A&quot;, &quot;B&quot;)# 条件边：根据条件决定下一步workflow.add_conditional_edges( &quot;A&quot;, 决策函数, &#123;&quot;条件1&quot;: &quot;B&quot;, &quot;条件2&quot;: &quot;C&quot;&#125;) 第四章 第一个程序让我们写一个最简单的计数器程序，理解状态是怎么流转的。 完整代码123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960from langgraph.graph import StateGraph, START, ENDfrom typing_extensions import TypedDict# 1. 定义状态结构class CounterState(TypedDict): count: int history: list[str]# 2. 定义节点函数def increment_node(state: CounterState): &quot;&quot;&quot;计数器 +1&quot;&quot;&quot; new_count = state[&quot;count&quot;] + 1 message = f&quot;count: &#123;state[&#x27;count&#x27;]&#125; → &#123;new_count&#125;&quot; return &#123; &quot;count&quot;: new_count, &quot;history&quot;: state[&quot;history&quot;] + [message] &#125;def double_node(state: CounterState): &quot;&quot;&quot;计数器翻倍&quot;&quot;&quot; new_count = state[&quot;count&quot;] * 2 message = f&quot;count: &#123;state[&#x27;count&#x27;]&#125; → &#123;new_count&#125;&quot; return &#123; &quot;count&quot;: new_count, &quot;history&quot;: state[&quot;history&quot;] + [message] &#125;def report_node(state: CounterState): &quot;&quot;&quot;报告结果&quot;&quot;&quot; return &#123;&quot;history&quot;: state[&quot;history&quot;] + [f&quot;最终结果: &#123;state[&#x27;count&#x27;]&#125;&quot;]&#125;# 3. 创建图workflow = StateGraph(CounterState)# 4. 添加节点workflow.add_node(&quot;increment&quot;, increment_node)workflow.add_node(&quot;double&quot;, double_node)workflow.add_node(&quot;report&quot;, report_node)# 5. 连接节点workflow.add_edge(START, &quot;increment&quot;)workflow.add_edge(&quot;increment&quot;, &quot;double&quot;)workflow.add_edge(&quot;double&quot;, &quot;report&quot;)workflow.add_edge(&quot;report&quot;, END)# 6. 编译app = workflow.compile()# 7. 运行result = app.invoke(&#123; &quot;count&quot;: 5, &quot;history&quot;: [&quot;开始执行&quot;]&#125;)print(&quot;执行历史:&quot;)for step in result[&quot;history&quot;]: print(f&quot; - &#123;step&#125;&quot;)print(f&quot;
最终计数: &#123;result[&#x27;count&#x27;]&#125;&quot;) 运行结果1234567执行历史: - 开始执行 - count: 5 → 6 - count: 6 → 12 - 最终结果: 12最终计数: 12 关键点 只返回需要更新的字段：节点不用返回完整的 state，只返回变化的部分 状态自动传递：每个节点执行完，更新后的状态自动传给下一个节点 必须编译：调用 compile() 后才能运行 第五章 Reducer 机制这是很多人一开始搞不明白的点：为什么有时候状态会被覆盖，有时候会累加？ 答案就是 Reducer。 问题：状态被覆盖默认情况下，每个节点返回的值会覆盖之前的值： 123456class State(TypedDict): score: int # 普通定义# Node1 返回 &#123;&quot;score&quot;: 10&#125; → state[&quot;score&quot;] = 10# Node2 返回 &#123;&quot;score&quot;: 20&#125; → state[&quot;score&quot;] = 20 (覆盖了!)# 最终 score = 20 解决方案：使用 Reducer123456789from typing import Annotatedimport operatorclass State(TypedDict): score: Annotated[int, operator.add] # 使用 operator.add 作为 reducer# Node1 返回 &#123;&quot;score&quot;: 10&#125; → state[&quot;score&quot;] = 0 + 10 = 10# Node2 返回 &#123;&quot;score&quot;: 20&#125; → state[&quot;score&quot;] = 10 + 20 = 30# 最终 score = 30 (累加!) 实际例子：游戏得分1234567891011121314151617181920212223242526272829303132333435from langgraph.graph import StateGraph, START, ENDfrom typing_extensions import TypedDictfrom typing import Annotatedimport operatorclass ScoreState(TypedDict): player_name: str # 普通字段，会被覆盖 score: Annotated[int, operator.add] # 累加 actions: Annotated[list[str], operator.add] # 列表也能累加def level1_node(state): return &#123;&quot;score&quot;: 10, &quot;actions&quot;: [&quot;通关第一关&quot;]&#125;def level2_node(state): return &#123;&quot;score&quot;: 20, &quot;actions&quot;: [&quot;通关第二关&quot;]&#125;def level3_node(state): return &#123;&quot;score&quot;: 30, &quot;actions&quot;: [&quot;通关第三关&quot;]&#125;# 构建图...workflow = StateGraph(ScoreState)workflow.add_node(&quot;level1&quot;, level1_node)workflow.add_node(&quot;level2&quot;, level2_node)workflow.add_node(&quot;level3&quot;, level3_node)workflow.add_edge(START, &quot;level1&quot;)workflow.add_edge(&quot;level1&quot;, &quot;level2&quot;)workflow.add_edge(&quot;level2&quot;, &quot;level3&quot;)workflow.add_edge(&quot;level3&quot;, END)app = workflow.compile()result = app.invoke(&#123;&quot;player_name&quot;: &quot;小明&quot;, &quot;score&quot;: 0, &quot;actions&quot;: []&#125;)print(f&quot;玩家: &#123;result[&#x27;player_name&#x27;]&#125;&quot;)print(f&quot;总分: &#123;result[&#x27;score&#x27;]&#125;&quot;) # 10+20+30=60print(f&quot;完成动作: &#123;result[&#x27;actions&#x27;]&#125;&quot;) 常用 Reducer Reducer 作用 适用场景 operator.add 数值相加 计数、得分 operator.add 列表拼接 历史记录、消息列表 add_messages 消息智能合并 聊天历史 第六章 条件分支真实的应用不可能一条路走到黑，肯定需要根据情况走不同的路。 关键函数：add_conditional_edges12345678workflow.add_conditional_edges( &quot;source_node&quot;, # 从哪个节点出发 routing_function, # 用什么函数决定路由 &#123; # 路由映射表 &quot;result1&quot;: &quot;target_node1&quot;, &quot;result2&quot;: &quot;target_node2&quot;, &#125;) 实际例子：智能客服路由12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455565758596061626364656667686970717273747576777879808182from langgraph.graph import StateGraph, START, ENDfrom typing_extensions import TypedDictclass CustomerState(TypedDict): question: str category: str answer: str# 分类节点def classify_question(state: CustomerState): question = state[&quot;question&quot;].lower() if &quot;退款&quot; in question or &quot;退货&quot; in question: category = &quot;refund&quot; elif &quot;物流&quot; in question or &quot;配送&quot; in question: category = &quot;shipping&quot; elif &quot;产品&quot; in question or &quot;使用&quot; in question: category = &quot;product&quot; else: category = &quot;general&quot; return &#123;&quot;category&quot;: category&#125;# 处理节点def handle_refund(state): return &#123;&quot;answer&quot;: &quot;退款专员：请提供订单号，3个工作日内处理。&quot;&#125;def handle_shipping(state): return &#123;&quot;answer&quot;: &quot;物流客服：您的包裹正在配送中。&quot;&#125;def handle_product(state): return &#123;&quot;answer&quot;: &quot;产品顾问：请查看说明书第3页。&quot;&#125;def handle_general(state): return &#123;&quot;answer&quot;: &quot;客服：感谢咨询，还有其他问题吗？&quot;&#125;# 路由函数def route_question(state: CustomerState) -&gt; str: return state[&quot;category&quot;]# 构建图workflow = StateGraph(CustomerState)workflow.add_node(&quot;classify&quot;, classify_question)workflow.add_node(&quot;refund&quot;, handle_refund)workflow.add_node(&quot;shipping&quot;, handle_shipping)workflow.add_node(&quot;product&quot;, handle_product)workflow.add_node(&quot;general&quot;, handle_general)workflow.add_edge(START, &quot;classify&quot;)# 关键：条件路由workflow.add_conditional_edges( &quot;classify&quot;, route_question, &#123; &quot;refund&quot;: &quot;refund&quot;, &quot;shipping&quot;: &quot;shipping&quot;, &quot;product&quot;: &quot;product&quot;, &quot;general&quot;: &quot;general&quot; &#125;)# 所有分支都到 ENDworkflow.add_edge(&quot;refund&quot;, END)workflow.add_edge(&quot;shipping&quot;, END)workflow.add_edge(&quot;product&quot;, END)workflow.add_edge(&quot;general&quot;, END)app = workflow.compile()# 测试test_questions = [ &quot;我想申请退款&quot;, &quot;我的快递到哪了？&quot;, &quot;这个产品怎么使用？&quot;,]for q in test_questions: result = app.invoke(&#123;&quot;question&quot;: q, &quot;category&quot;: &quot;&quot;, &quot;answer&quot;: &quot;&quot;&#125;) print(f&quot;问题: &#123;q&#125;&quot;) print(f&quot;回答: &#123;result[&#x27;answer&#x27;]&#125;
&quot;) 第七章 循环流程有时候一次处理不够好，需要反复迭代优化。LangGraph 天然支持循环。 关键点 条件边可以指回前面的节点：形成循环 必须有退出条件：否则会无限循环 建议设置最大迭代次数：兜底保护 实际例子：答案优化器1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162636465666768697071727374757677787980from langgraph.graph import StateGraph, START, ENDfrom typing_extensions import TypedDictfrom typing import Annotatedimport operatorclass ImprovementState(TypedDict): question: str answer: str quality_score: float iteration: Annotated[int, operator.add] max_iterations: intdef generate_answer(state: ImprovementState): &quot;&quot;&quot;生成或改进答案&quot;&quot;&quot; iteration = state.get(&quot;iteration&quot;, 0) # 模拟答案逐步改进 if iteration == 0: answer = &quot;简单回答：这是一个基础答案。&quot; score = 0.5 elif iteration == 1: answer = &quot;改进回答：这是一个更详细的答案，包含更多信息。&quot; score = 0.7 else: answer = &quot;完善回答：经过仔细思考的完整答案，包含背景和建议。&quot; score = 0.9 print(f&quot;第&#123;iteration + 1&#125;次生成 (质量: &#123;score&#125;)&quot;) return &#123; &quot;answer&quot;: answer, &quot;quality_score&quot;: score, &quot;iteration&quot;: 1 # 每次+1（因为有 reducer） &#125;def check_quality(state): &quot;&quot;&quot;检查质量，不更新状态&quot;&quot;&quot; return statedef should_continue(state: ImprovementState) -&gt; str: &quot;&quot;&quot;决定是继续还是结束&quot;&quot;&quot; if state[&quot;quality_score&quot;] &gt;= 0.8: return &quot;done&quot; elif state[&quot;iteration&quot;] &gt;= state[&quot;max_iterations&quot;]: return &quot;done&quot; else: return &quot;improve&quot;# 构建带循环的图workflow = StateGraph(ImprovementState)workflow.add_node(&quot;generate&quot;, generate_answer)workflow.add_node(&quot;check&quot;, check_quality)workflow.add_edge(START, &quot;generate&quot;)workflow.add_edge(&quot;generate&quot;, &quot;check&quot;)# 关键：条件边可以循环回去workflow.add_conditional_edges( &quot;check&quot;, should_continue, &#123; &quot;improve&quot;: &quot;generate&quot;, # 循环 &quot;done&quot;: END # 结束 &#125;)app = workflow.compile()result = app.invoke(&#123; &quot;question&quot;: &quot;什么是人工智能？&quot;, &quot;answer&quot;: &quot;&quot;, &quot;quality_score&quot;: 0.0, &quot;iteration&quot;: 0, &quot;max_iterations&quot;: 5&#125;)print(f&quot;
最终答案: &#123;result[&#x27;answer&#x27;]&#125;&quot;)print(f&quot;最终质量: &#123;result[&#x27;quality_score&#x27;]&#125;&quot;)print(f&quot;迭代次数: &#123;result[&#x27;iteration&#x27;]&#125;&quot;) 第八章 聊天机器人做聊天机器人最头疼的是消息历史管理。LangGraph 提供了专门的工具来解决这个问题。 核心：MessagesState 和 add_messages12345678910111213from langgraph.graph import MessagesStatefrom langgraph.graph.message import add_messagesfrom langchain_core.messages import HumanMessage, AIMessage# 方式1：继承 MessagesStateclass ChatState(MessagesState): user_name: str conversation_count: int# 方式2：手动定义class ChatState(TypedDict): messages: Annotated[list[BaseMessage], add_messages] user_name: str add_messages 是一个智能 Reducer，它会： 自动追加新消息 处理消息 ID 去重 保持消息顺序 完整聊天机器人1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950import osfrom langgraph.graph import StateGraph, START, END, MessagesStatefrom langchain_core.messages import HumanMessage, AIMessage, SystemMessagefrom langchain_community.llms import Tongyios.environ[&quot;DASHSCOPE_API_KEY&quot;] = &quot;your-key&quot;llm = Tongyi(model=&quot;qwen-plus&quot;, temperature=0.7)class ChatState(MessagesState): user_name: str conversation_count: intdef chatbot_node(state: ChatState): &quot;&quot;&quot;聊天节点&quot;&quot;&quot; # 构建系统提示 system_prompt = f&quot;&quot;&quot;你是一个友好的AI助手。用户名: &#123;state.get(&#x27;user_name&#x27;, &#x27;用户&#x27;)&#125;当前是第 &#123;state.get(&#x27;conversation_count&#x27;, 0)&#125; 轮对话。&quot;&quot;&quot; messages = [SystemMessage(content=system_prompt)] + state[&quot;messages&quot;] response = llm.invoke(messages) return &#123; &quot;messages&quot;: [AIMessage(content=response)], &quot;conversation_count&quot;: state.get(&quot;conversation_count&quot;, 0) + 1 &#125;# 构建图workflow = StateGraph(ChatState)workflow.add_node(&quot;chatbot&quot;, chatbot_node)workflow.add_edge(START, &quot;chatbot&quot;)workflow.add_edge(&quot;chatbot&quot;, END)app = workflow.compile()# 多轮对话state = &#123;&quot;messages&quot;: [], &quot;user_name&quot;: &quot;小明&quot;, &quot;conversation_count&quot;: 0&#125;conversations = [ &quot;你好，我是小明&quot;, &quot;我刚才说我叫什么？&quot;, &quot;帮我推荐一本Python书&quot;]for user_input in conversations: print(f&quot;用户: &#123;user_input&#125;&quot;) state[&quot;messages&quot;].append(HumanMessage(content=user_input)) result = app.invoke(state) state = result print(f&quot;助手: &#123;result[&#x27;messages&#x27;][-1].content&#125;
&quot;) 第九章 Agent 工具调用Agent 和普通聊天机器人的区别是：Agent 能使用工具。 定义工具使用 @tool 装饰器： 12345678910111213141516171819202122232425262728293031323334353637from langchain_core.tools import tool@tooldef search_web(query: str) -&gt; str: &quot;&quot;&quot;搜索网络信息 Args: query: 搜索关键词 &quot;&quot;&quot; # 实际实现 return f&quot;搜索 &#x27;&#123;query&#125;&#x27; 的结果：...&quot;@tooldef calculator(expression: str) -&gt; str: &quot;&quot;&quot;计算数学表达式 Args: expression: 数学表达式，如 &quot;2+2&quot; &quot;&quot;&quot; try: result = eval(expression) return f&quot;计算结果: &#123;expression&#125; = &#123;result&#125;&quot; except: return &quot;计算错误&quot;@tooldef get_weather(city: str) -&gt; str: &quot;&quot;&quot;查询城市天气 Args: city: 城市名称 &quot;&quot;&quot; weather_data = &#123; &quot;北京&quot;: &quot;晴天，15-25度&quot;, &quot;上海&quot;: &quot;多云，18-28度&quot;, &#125; return weather_data.get(city, f&quot;&#123;city&#125;天气信息不可用&quot;) 工具定义要点 必须有 docstring：描述工具用途，AI 靠这个判断什么时候用 参数要有类型注解：让 AI 知道怎么传参 Args 部分详细说明：每个参数是干什么的 第十章 ReAct AgentReAct = Reasoning + Acting，是目前最流行的 Agent 架构。 工作流程 Thought：AI 思考需要做什么 Action：选择并调用工具 Observation：观察工具返回结果 重复：直到任务完成 使用预置组件LangGraph 提供了现成的组件： 123456789101112131415161718192021222324252627282930from langgraph.prebuilt import create_react_agent, ToolNodefrom langchain_community.chat_models import ChatTongyifrom langchain_core.tools import toolfrom langchain_core.messages import SystemMessage@tooldef add(a: float, b: float) -&gt; float: &quot;&quot;&quot;两数相加&quot;&quot;&quot; return a + b@tooldef multiply(a: float, b: float) -&gt; float: &quot;&quot;&quot;两数相乘&quot;&quot;&quot; return a * b# 创建模型llm = ChatTongyi(model=&quot;qwen-plus&quot;, temperature=0.7)# 创建 ReAct Agentagent = create_react_agent( model=llm, tools=[add, multiply], messages_modifier=SystemMessage(content=&quot;你是一个数学计算助手。&quot;))# 使用result = agent.invoke(&#123; &quot;messages&quot;: [&#123;&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: &quot;计算 (10 + 5) × 3&quot;&#125;]&#125;)print(result[&quot;messages&quot;][-1].content) 手动实现 ReAct Agent如果需要完全控制，可以手动实现： 12345678910111213141516171819202122232425262728293031323334353637383940414243from langgraph.graph import StateGraph, START, ENDfrom langgraph.graph.message import add_messagesfrom langgraph.prebuilt import ToolNodefrom typing import Annotated, Literalfrom typing_extensions import TypedDictclass AgentState(TypedDict): messages: Annotated[list, add_messages] iterations: Annotated[int, operator.add]# 工具定义...tools = [python_executor, text_analyzer]tool_node = ToolNode(tools)# 模型绑定工具llm_with_tools = llm.bind_tools(tools)def call_model(state: AgentState): &quot;&quot;&quot;调用模型决策&quot;&quot;&quot; messages = state[&quot;messages&quot;] response = llm_with_tools.invoke(messages) return &#123;&quot;messages&quot;: [response], &quot;iterations&quot;: 1&#125;def should_continue(state) -&gt; Literal[&quot;tools&quot;, &quot;__end__&quot;]: &quot;&quot;&quot;判断是否需要调用工具&quot;&quot;&quot; last_message = state[&quot;messages&quot;][-1] if hasattr(last_message, &quot;tool_calls&quot;) and last_message.tool_calls: return &quot;tools&quot; return &quot;__end__&quot;# 构建图workflow = StateGraph(AgentState)workflow.add_node(&quot;agent&quot;, call_model)workflow.add_node(&quot;tools&quot;, tool_node)workflow.add_edge(START, &quot;agent&quot;)workflow.add_conditional_edges(&quot;agent&quot;, should_continue, &#123; &quot;tools&quot;: &quot;tools&quot;, &quot;__end__&quot;: END&#125;)workflow.add_edge(&quot;tools&quot;, &quot;agent&quot;)app = workflow.compile() 第十一章 多Agent协作当任务复杂时，一个 Agent 搞不定，需要多个专业 Agent 配合。 Supervisor 模式 核心思想：一个 Supervisor 负责调度，多个专业 Agent 负责执行。 完整实现123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990919293949596979899100101102103104105106107108109110111112113114115116117118119120121122123124from langgraph.graph import StateGraph, START, ENDfrom langchain_core.messages import HumanMessage, AIMessage, BaseMessagefrom langchain_core.tools import toolfrom typing import Annotated, Literal, Sequencefrom typing_extensions import TypedDictfrom langgraph.graph.message import add_messages# 1. 定义状态class SupervisorState(TypedDict): messages: Annotated[Sequence[BaseMessage], add_messages] next: str # 下一个执行的 Agent# 2. 定义各种工具@tooldef check_system_status(component: str) -&gt; str: &quot;&quot;&quot;检查系统组件状态&quot;&quot;&quot; status = &#123;&quot;database&quot;: &quot;正常&quot;, &quot;server&quot;: &quot;负载高&quot;, &quot;api&quot;: &quot;正常&quot;&#125; return status.get(component, &quot;未知&quot;)@tooldef get_product_info(product_name: str) -&gt; str: &quot;&quot;&quot;获取产品信息&quot;&quot;&quot; products = &#123; &quot;基础版&quot;: &quot;99元/月，基础功能&quot;, &quot;专业版&quot;: &quot;299元/月，高级功能&quot;, &#125; return products.get(product_name, &quot;产品不存在&quot;)@tooldef query_invoice(order_id: str) -&gt; str: &quot;&quot;&quot;查询发票&quot;&quot;&quot; invoices = &#123;&quot;ORD001&quot;: &quot;已开具&quot;, &quot;ORD002&quot;: &quot;处理中&quot;&#125; return invoices.get(order_id, &quot;订单不存在&quot;)# 3. 定义专业 Agent 节点def tech_agent_node(state): &quot;&quot;&quot;技术支持 Agent&quot;&quot;&quot; last_message = state[&quot;messages&quot;][-1].content if &quot;系统&quot; in last_message or &quot;服务器&quot; in last_message: result = check_system_status.invoke(&#123;&quot;component&quot;: &quot;server&quot;&#125;) response = f&quot;【技术支持】系统状态: &#123;result&#125;&quot; else: response = &quot;【技术支持】请描述您遇到的技术问题。&quot; return &#123;&quot;messages&quot;: [AIMessage(content=response)]&#125;def sales_agent_node(state): &quot;&quot;&quot;销售 Agent&quot;&quot;&quot; last_message = state[&quot;messages&quot;][-1].content for product in [&quot;基础版&quot;, &quot;专业版&quot;]: if product in last_message: info = get_product_info.invoke(&#123;&quot;product_name&quot;: product&#125;) return &#123;&quot;messages&quot;: [AIMessage(content=f&quot;【销售顾问】&#123;info&#125;&quot;)]&#125; return &#123;&quot;messages&quot;: [AIMessage(content=&quot;【销售顾问】我们有基础版和专业版，需要了解哪个？&quot;)]&#125;def billing_agent_node(state): &quot;&quot;&quot;账单 Agent&quot;&quot;&quot; return &#123;&quot;messages&quot;: [AIMessage(content=&quot;【账单专员】请提供订单号，我来查询。&quot;)]&#125;# 4. Supervisor 节点def supervisor_node(state): &quot;&quot;&quot;Supervisor：决定下一步&quot;&quot;&quot; last_message = state[&quot;messages&quot;][-1].content tech_keywords = [&quot;错误&quot;, &quot;bug&quot;, &quot;崩溃&quot;, &quot;系统&quot;, &quot;服务器&quot;] sales_keywords = [&quot;价格&quot;, &quot;购买&quot;, &quot;产品&quot;, &quot;套餐&quot;] billing_keywords = [&quot;发票&quot;, &quot;支付&quot;, &quot;退款&quot;, &quot;账单&quot;] if any(kw in last_message for kw in tech_keywords): next_agent = &quot;tech_support&quot; elif any(kw in last_message for kw in sales_keywords): next_agent = &quot;sales&quot; elif any(kw in last_message for kw in billing_keywords): next_agent = &quot;billing&quot; else: next_agent = &quot;sales&quot; # 默认销售 return &#123;&quot;next&quot;: next_agent&#125;# 5. 路由函数def route_after_supervisor(state) -&gt; Literal[&quot;tech_support&quot;, &quot;sales&quot;, &quot;billing&quot;]: return state[&quot;next&quot;]# 6. 构建图workflow = StateGraph(SupervisorState)workflow.add_node(&quot;supervisor&quot;, supervisor_node)workflow.add_node(&quot;tech_support&quot;, tech_agent_node)workflow.add_node(&quot;sales&quot;, sales_agent_node)workflow.add_node(&quot;billing&quot;, billing_agent_node)workflow.add_edge(START, &quot;supervisor&quot;)workflow.add_conditional_edges( &quot;supervisor&quot;, route_after_supervisor, &#123; &quot;tech_support&quot;: &quot;tech_support&quot;, &quot;sales&quot;: &quot;sales&quot;, &quot;billing&quot;: &quot;billing&quot;, &#125;)workflow.add_edge(&quot;tech_support&quot;, END)workflow.add_edge(&quot;sales&quot;, END)workflow.add_edge(&quot;billing&quot;, END)app = workflow.compile()# 7. 测试test_cases = [ &quot;我遇到500错误，系统无法访问&quot;, &quot;专业版多少钱？&quot;, &quot;我需要查发票&quot;,]for query in test_cases: print(f&quot;用户: &#123;query&#125;&quot;) result = app.invoke(&#123;&quot;messages&quot;: [HumanMessage(content=query)], &quot;next&quot;: &quot;&quot;&#125;) for msg in result[&quot;messages&quot;]: if isinstance(msg, AIMessage): print(msg.content) print() 第十二章 实战项目智能客服系统架构把前面学的所有东西整合起来，做一个完整的智能客服系统： Supervisor 分析问题类型 技术支持 Agent 处理技术问题 销售顾问 Agent 处理产品咨询 账单专员 Agent 处理财务问题 每个 Agent 都有自己的专业工具 支持多轮对话和历史记忆 完整代码见附带的 langgraph_supervisor_1.py 文件。 第十三章 进阶话题 持久化和记忆 使用 checkpointer 保存对话状态： 12345678from langgraph.checkpoint.memory import MemorySavermemory = MemorySaver()app = workflow.compile(checkpointer=memory)# 使用 thread_id 管理不同会话config = &#123;&quot;configurable&quot;: &#123;&quot;thread_id&quot;: &quot;user_123&quot;&#125;&#125;result = app.invoke(state, config=config) 流式输出 实现打字机效果： 123456789# 方式1：使用 streaming=True 的模型llm = Tongyi(model=&quot;qwen-plus&quot;, streaming=True)for chunk in llm.stream(messages): print(chunk, end=&quot;&quot;, flush=True)# 方式2：使用 app.stream()for event in app.stream(initial_state): print(event) 子图（Subgraph） 复杂系统可以拆成多个子图： 1234567# 定义子图sub_workflow = StateGraph(SubState)# ... 添加节点和边sub_graph = sub_workflow.compile()# 在主图中使用子图作为节点main_workflow.add_node(&quot;sub_process&quot;, sub_graph) Human-in-the-Loop 让人类参与决策： 1234567891011# 设置断点app = workflow.compile( checkpointer=memory, interrupt_before=[&quot;sensitive_action&quot;])# 运行到断点会暂停result = app.invoke(state, config)# 人工审核后继续app.invoke(None, config) # 继续执行 调试技巧 123456# 可视化图结构print(app.get_graph().draw_mermaid())# 打印执行过程for event in app.stream(state, stream_mode=&quot;debug&quot;): print(event)

【大模型AI Agent 入门到实战】深度理解 Agent 全链路逻辑与工程化落地 【Agent入门到实战】深度理解Agent全链路内容和深度优化、系统评估1.重新定义 Agent：从「工具调用」到「自主智能体」1.1 智能体的核心进化逻辑传统大模型的交互模式停留在「问答响应」层面，用户提出需求后，模型仅能输出建议性内容（如旅行规划的文字建议），但落地执行仍需用户手动完成；而 AI Agent 的核心突破在于闭环执行能力—— 它不是「给答案」，而是「做事情」。 举个例子： 你：「帮我规划北京→成都 3 天亲子游，预算 6000」 传统 LLM：「6000元的预算，想带家人来一场说走就走的旅行，可以考虑一下春秋航空亲子套票。这个方案最省心，可以最大程度地降低您的交通成本，让预算更多地投入到住宿和游玩体验上……」 你：（需要自己去各个网站查机票、订酒店、规划路线） AI Agent的体验： 你：「帮我规划北京→成都 3 天亲子游，预算 6000」 Agent：（自动搜索机票价格）→（比较酒店并筛选）→（规划每日行程）→（计算预算） Agent：「已为您完成规划！往返机票1800元，住宿2晚1200元，包含成都大熊猫繁育研究基地、成都自然博物馆等5个景点的详细行程，总预算4800元。[查看完整计划.pdf]」 这就是最本质的区别：Agent 具备目标拆解 - 资源调用 - 结果落地的全流程自主能力，而非单纯的信息整合，也就是说传统LLM给建议，Agent却能帮你干活。 1.2 Agent的核心定义AI Agent（智能体） 是一个具备以下三大能力的智能系统： 自主感知：能够理解当前环境和任务需求 自主决策：能够制定执行计划并动态调整 自主执行：能够调用工具完成实际任务 用一句话总结：Agent = LLM（大脑-认知核心） + 工具生态（手脚-执行载体） + 记忆系统（经验沉淀） + 规划引擎（智慧-策略制定） 2.Agent 核心架构：从分层设计到数据流转逻辑2.1 Agent整体架构图让我们先看一张完整的Agent架构图，理解各个组件如何协同工作： 2.2 架构分层解析这个架构可以分为四个核心层： 层级 核心作用 技术载体 类比 核心挑战 感知层 意图解析与输入标准化 LLM + 意图识别 人类感官 多模态输入理解、歧义消解 认知层 推理、规划、决策 LLM + 规划算法 人类大脑 复杂任务拆解、逻辑一致性 执行层 工具调用与任务落地 工具注册中心 + 调用适配器 人类手脚 工具兼容性、执行容错 记忆层 信息存储与精准检索 短期缓存 + 向量数据库 人类记忆 上下文压缩、长期记忆召回 第一层：感知层（Perception Layer） 作用：接收并理解用户输入 组件：用户输入 → 大语言模型理解 类比：就像人的耳朵和眼睛 第二层：认知层（Cognition Layer） 作用：分析、推理、规划 组件：LLM Brain + 规划模块 + 推理引擎 类比：就像人的大脑 第三层：执行层（Execution Layer） 作用：调用各种工具完成任务 组件：工具集（搜索、代码、API等） 类比：就像人的手脚 第四层：记忆层（Memory Layer） 作用：存储和检索信息 组件：短期记忆 + 长期记忆 类比：就像人的记忆系统 2.3 数据流转过程我们可以用一个具体例子说明数据如何在架构中流转： 任务：「找出2024年诺贝尔物理学奖获得者，并总结他们的主要贡献」 1234567891011121314151617181920212223步骤1: 用户输入 → 进入规划模块：识别需要「搜索」和「总结」两个步骤步骤2: 规划完成 → 进入推理引擎（ReAct框架）步骤3: 第一轮思考-行动-观察循环 Thought: &quot;我需要搜索2024年诺贝尔物理学奖获得者&quot; Action: 调用搜索工具search(&quot;2024 Nobel Prize Physics&quot;) Observation: 获得搜索结果→ &quot;John Hopfield和Geoffrey Hinton&quot;步骤4: 第二轮思考-行动-观察循环 Thought: &quot;我需要了解他们的贡献&quot; Action: 调用搜索工具search(&quot;Hopfield Hinton 神经网络贡献&quot;) Observation: 获得详细信息→ &quot;人工神经网络和机器学习基础&quot;步骤5: 综合信息 → LLM整合所有观察结果 → 生成结构化答案 → 存入记忆模块（长期记忆）步骤6: 输出结果 → 返回完整答案给用户 这个过程中，Agent不是一次性生成答案，而是通过多轮思考-行动-观察的循环，逐步接近最终答案。这就是Agent比传统LLM强大的地方。 3.Agent 四大核心模块3.1 组成部分总览 3.2 组成部分一：大语言模型（LLM Brain）作用与地位大语言模型是智能 Agent 的核心大脑，承担核心认知、推理、决策与输出工作，具体能力如下： 解析并理解用户指令与真实意图 开展逻辑思考，梳理完整推理链路 根据任务需求，自主选择并调用对应工具 整合多方信息，最终生成完整应答与结果 当前主流选择 模型 优势 适用场景 成本 GPT-4 / Claude 强大推理能力 复杂任务、高精度 高 DeepSeek-R1 性价比高、推理能力强 企业级部署 低 Gemini 2.0 多模态、Agent优化 需要视觉理解 中 实际代码示例1234567891011121314151617181920from langchain_openai import ChatOpenAI# 初始化LLM作为Agent的大脑llm = ChatOpenAI( model=&quot;gpt-4&quot;, temperature=0, # 降低随机性，提高推理稳定性)# LLM的推理能力展示response = llm.invoke( &quot;你需要查找2024年奥运会金牌榜，然后比较中美两国的金牌数。请分步思考如何完成这个任务。&quot;)print(response.content)# 输出示例：# 思考步骤：# 1. 首先需要调用搜索工具查找&quot;2024奥运会金牌榜&quot;# 2. 从搜索结果中提取中国和美国的金牌数# 3. 进行数值比较# 4. 生成比较结果 关键点： temperature=0：让Agent在推理时更稳定、更可预测 提示词需要引导「分步思考」，这是CoT（Chain of Thought）的核心 3.3 组成部分二：规划模块（Planning）规划模块是智能Agent的核心中枢模块，承担任务拆解、流程梳理、路径统筹的核心作用。区别于即时响应、被动执行的基础程序，具备规划能力的Agent，能够面对复杂、模糊、多步骤的复合型任务，主动梳理执行逻辑、拆解任务层级、明确执行顺序，从根源上规避盲目执行、遗漏步骤、重复运算等问题，是Agent实现自主、高效、闭环完成复杂任务的核心保障。 为什么需要规划？以典型复杂任务「帮我准备一场技术分享会」为例，可以直观对比出无规划Agent与有规划Agent的执行差异。 没有规划的Agent会： 无法拆解整体任务，不清楚从哪里开始，只能随机输出零散内容 筹备技术分享会涉及定位、资料、内容、演示、宣讲等多个核心环节，没有规划的Agent可能遗漏重要步骤 会反复重复检索同类资料、多次修改零散内容、无效推敲细节，浪费大量token重复思考 有规划的Agent会： 12345确定主题和目标听众搜索相关技术资料设计PPT大纲准备演示Demo生成演讲稿 两种主流规划方法方法一：ReAct框架（边想边做） 暂时无法在飞书文档外展示此内容 ReAct特点： ✅ 灵活：可以根据中间结果调整计划（思考→行动→观察循环） ✅ 适合探索性任务 ❌ Token消耗大：每一步都要调用LLM 方法二：Plan-and-Execute（先计划后执行） 暂时无法在飞书文档外展示此内容 Plan-and-Execute特点： ✅ 高效：只需调用一次LLM规划（先全量规划→再按计划执行） ✅ 可并行执行多个任务 ❌ 不灵活：难以根据中间结果调整，适合流程固定的标准化任务 实际代码对比ReAct实现： 12345678910111213141516171819202122232425262728from langchain.agents import create_react_agent, AgentExecutorfrom langchain.tools import Tool# 定义工具search_tool = Tool( name=&quot;Search&quot;, func=search_function, description=&quot;搜索互联网信息&quot;)# 创建ReAct Agentagent = create_react_agent(llm, [search_tool])agent_executor = AgentExecutor(agent=agent, tools=[search_tool], verbose=True)# 执行任务result = agent_executor.invoke(&#123; &quot;input&quot;: &quot;找出DeepSeek-R1的训练成本，并与GPT-4对比&quot;&#125;)# 输出过程（verbose=True会显示）：# Thought: 我需要搜索DeepSeek-R1的信息# Action: Search(&quot;DeepSeek-R1 training cost&quot;)# Observation: [搜索结果]# Thought: 接下来需要搜索GPT-4的成本# Action: Search(&quot;GPT-4 training cost&quot;)# Observation: [搜索结果]# Thought: 现在可以进行对比了# Final Answer: [对比结果] Plan-and-Execute实现： 123456789101112131415from langchain.agents import Plan, Execute# 第一步：规划planner = create_planner(llm)plan = planner.plan(&quot;分析2024年AI Agent市场趋势&quot;)# 输出的计划：# Task 1: 搜索2024年AI Agent市场报告# Task 2: 提取市场规模数据# Task 3: 识别主要参与者# Task 4: 总结趋势和预测# 第二步：执行executor = create_executor(tools)results = executor.execute(plan) # 按计划依次执行 选择建议 探索性任务（不知道中间会遇到什么）→ 用ReAct 流程明确的任务（步骤固定）→ 用Plan-and-Execute 复杂混合任务 → 两者结合 3.4 组成部分三：记忆模块（Memory）—— 让 Agent「记住关键信息」为什么记忆很重要？想象一下这个场景： 无记忆的 Agent：每次对话都是 “新开始”，完全不记得你之前说过什么。比如你说过 “我在北京工作”，后续让它推荐餐厅，仍会问 “你所在城市？” 有记忆的 Agent：能留存上下文和用户偏好，交互更贴合需求 —— 这是 Agent “拟人化” 的关键。 记忆的价值，就是从「一次性对话」到「持续交互」。记忆分为两类： 短期记忆（Short-term Memory）作用：保存当前任务的上下文 存储内容： 当前对话历史 中间步骤（执行）的结果 临时变量和状态 技术实现： 12345678910111213141516171819202122from langchain.memory import ConversationBufferMemory# 创建对话记忆memory = ConversationBufferMemory( memory_key=&quot;chat_history&quot;, return_messages=True)# Agent执行时自动记录agent_executor = AgentExecutor( agent=agent, tools=tools, memory=memory, # 添加记忆 verbose=True)# 第一轮对话agent_executor.invoke(&#123;&quot;input&quot;: &quot;我叫张三，在北京工作&quot;&#125;)# 第二轮对话（Agent会记得上下文）agent_executor.invoke(&#123;&quot;input&quot;: &quot;帮我推荐北京的餐厅&quot;&#125;)# Agent会知道你在北京，直接推荐北京的餐厅 短期记忆的挑战： 📊 Token限制：GPT-4有128K token限制，长对话会超出 💰 成本问题：每次调用都要把整个历史发送给LLM 解决方案： 1234567891011from langchain.memory import ConversationSummaryMemory# 使用摘要记忆：自动总结历史对话summary_memory = ConversationSummaryMemory( llm=llm, max_token_limit=2000 # 超过限制时自动总结)# 效果：# 原始历史（5000 tokens）→ 总结后（500 tokens）# &quot;用户是张三，在北京工作，偏好川菜，预算500元以内&quot; 长期记忆（Long-term Memory）作用：存储可复用的知识和经验 存储内容： 用户的个人信息和偏好 历史任务的成功经验 领域知识库 工具使用的最佳实践 技术实现：使用向量数据库 123456789101112131415161718192021222324252627282930from langchain.vectorstores import Chromafrom langchain.embeddings import OpenAIEmbeddings# 1. 创建向量数据库（长期记忆）embeddings = OpenAIEmbeddings()vectorstore = Chroma( collection_name=&quot;agent_memory&quot;, embedding_function=embeddings)# 2. 存储经验vectorstore.add_texts([ &quot;用户张三偏好川菜，预算500元&quot;, &quot;北京最佳川菜馆：川办、巴国布衣&quot;, &quot;搜索餐厅时应该考虑：位置、评分、价格、口味&quot;])# 3. Agent执行任务时检索相关记忆query = &quot;帮张三推荐餐厅&quot;relevant_memories = vectorstore.similarity_search(query, k=3)# 4. 将记忆注入到prompt中prompt = f&quot;&quot;&quot;相关记忆：&#123;relevant_memories&#125;用户请求：&#123;query&#125;请根据记忆中的信息给出推荐。&quot;&quot;&quot; 记忆架构图暂时无法在飞书文档外展示此内容 记忆模块的高级技巧技巧1：自动清理不重要的记忆 12345#基于重要性评分的记忆管理def should_store_in_long_term(message): # 让LLM判断是否重要 importance = llm.predict(f&quot;这条信息的重要性（1-10）：&#123;message&#125;&quot;) return int(importance) &gt;= 7 # 只存储重要度&gt;=7的信息 技巧2：记忆的时效性管理 123456789101112#给记忆加上时间戳from datetime import datetime, timedeltamemory_item = &#123; &quot;content&quot;: &quot;用户偏好川菜&quot;, &quot;timestamp&quot;: datetime.now(), &quot;expiry&quot;: datetime.now() + timedelta(days=30) # 30天后过期&#125;# 检索时过滤过期记忆def get_valid_memories(): return [m for m in memories if m[&quot;expiry&quot;] &gt; datetime.now()] 3.5 组成部分四：工具集（Tools）工具是Agent的手脚与「超能力」如果说LLM 是Agent的“大脑”，那工具就是Agent的「手脚」和「超能力」，没有工具的 Agent 只能 “纸上谈兵”；通过工具，Agent 能实现： 🔍 搜索互联网 💻 执行代码 📊 操作数据库 🔧 调用API 🖥️ 控制电脑 工具的定义与实现一个工具的标准结构： 123456789101112131415161718192021from langchain.tools import Tooldef calculate(expression: str) -&gt; str: &quot;&quot;&quot;执行数学计算&quot;&quot;&quot; try: result = eval(expression) # 实际生产中不要用eval return f&quot;计算结果：&#123;result&#125;&quot; except Exception as e: return f&quot;计算错误：&#123;str(e)&#125;&quot;# 定义工具calculator_tool = Tool( name=&quot;Calculator&quot;, # 工具名称（Agent会看到） func=calculate, # 工具函数 description=&quot;&quot;&quot; 用于数学计算。 输入：数学表达式字符串，如 &quot;2 + 2&quot; 或 &quot;sqrt(16)&quot; 输出：计算结果 何时使用：当需要进行精确数学计算时 &quot;&quot;&quot; # 描述很重要！Agent通过描述来决定是否使用该工具) 关键要素： 清晰的名称：Agent通过名称快速识别工具 详细的描述：告诉Agent什么时候用、怎么用 标准的输入输出：保证工具能被正确调用 常用工具类型与实现 搜索工具 123456789101112from langchain.tools import DuckDuckGoSearchRunsearch = DuckDuckGoSearchRun()search_tool = Tool( name=&quot;WebSearch&quot;, func=search.run, description=&quot;搜索互联网获取最新信息。适用于需要实时数据的场景。&quot;)# 使用示例result = search.run(&quot;2024年诺贝尔物理学奖&quot;) 代码执行工具 1234567891011121314151617181920212223242526def python_executor(code: str) -&gt; str: &quot;&quot;&quot;执行Python代码&quot;&quot;&quot; import io import sys from contextlib import redirect_stdout f = io.StringIO() try: with redirect_stdout(f): exec(code) return f.getvalue() except Exception as e: return f&quot;错误：&#123;str(e)&#125;&quot;code_tool = Tool( name=&quot;PythonExecutor&quot;, func=python_executor, description=&quot;执行Python代码。适用于数据处理、计算、可视化等任务。&quot;)# Agent可以这样用：# code_tool.run(&quot;&quot;&quot;# import pandas as pd# data = [1, 2, 3, 4, 5]# print(f&quot;平均值：&#123;sum(data)/len(data)&#125;&quot;)# &quot;&quot;&quot;) API调用工具 12345678910111213import requestsdef weather_api(city: str) -&gt; str: &quot;&quot;&quot;查询天气&quot;&quot;&quot; # 假设调用某个天气API response = requests.get(f&quot;https://api.weather.com/&#123;city&#125;&quot;) return response.json()weather_tool = Tool( name=&quot;WeatherAPI&quot;, func=weather_api, description=&quot;查询指定城市的天气信息。输入城市名，返回温度、湿度等信息。&quot;) 数据库工具 1234567891011121314151617181920import sqlite3def query_database(sql: str) -&gt; str: &quot;&quot;&quot;查询数据库&quot;&quot;&quot; conn = sqlite3.connect(&#x27;my_database.db&#x27;) cursor = conn.cursor() try: cursor.execute(sql) results = cursor.fetchall() return str(results) except Exception as e: return f&quot;查询错误：&#123;str(e)&#125;&quot; finally: conn.close()db_tool = Tool( name=&quot;DatabaseQuery&quot;, func=query_database, description=&quot;执行SQL查询。适用于需要从数据库获取数据的场景。&quot;) 工具组合的实际案例案例：构建一个数据分析Agent 123456789101112131415161718192021222324252627282930313233343536373839404142434445from langchain.agents import create_react_agent, AgentExecutorfrom langchain_openai import ChatOpenAI# 1. 准备工具集tools = [ search_tool, # 搜索数据 code_tool, # 数据处理 db_tool, # 数据库查询]# 2. 创建Agentllm = ChatOpenAI(model=&quot;gpt-4&quot;, temperature=0)agent = create_react_agent(llm, tools)agent_executor = AgentExecutor(agent=agent, tools=tools, verbose=True)# 3. 执行复杂任务result = agent_executor.invoke(&#123; &quot;input&quot;: &quot;&quot;&quot; 帮我分析一下： 1. 从数据库中查询2024年的销售数据 2. 搜索行业平均增长率 3. 用Python计算我们的增长率 4. 对比并给出结论 &quot;&quot;&quot;&#125;)# Agent的执行过程：# Thought: 需要先从数据库获取数据# Action: DatabaseQuery(&quot;SELECT * FROM sales WHERE year=2024&quot;)# Observation: [...数据...]# # Thought: 需要搜索行业数据# Action: WebSearch(&quot;2024年销售行业平均增长率&quot;)# Observation: [...行业数据...]# # Thought: 现在可以计算了# Action: PythonExecutor(&quot;# our_growth = (current - previous) / previous * 100# industry_avg = 15.2# print(f&#x27;我们的增长率：&#123;our_growth&#125;%，行业平均：&#123;industry_avg&#125;%&#x27;)# &quot;)# Observation: 我们的增长率：18.5%，行业平均：15.2%# # Thought: 可以给出结论了# Final Answer: [完整分析报告] 工具使用的最佳实践实践1：工具描述要精确，明确 “适用 / 不适用场景 + 输入输出格式”，减少 Agent 选错工具 ❌ 不好的描述： 1description=&quot;一个搜索工具&quot; ✅ 好的描述： 1234567description=&quot;&quot;&quot;搜索互联网获取最新信息。- 输入：搜索关键词（字符串）- 输出：相关网页内容摘要- 适用场景：需要实时数据、最新新闻、当前事件- 不适用场景：历史数据、个人信息、数学计算&quot;&quot;&quot; 实践2：工具要有错误处理，工具执行失败时，返回友好提示（比如 “API 超时，建议重试”） 12345678def safe_tool(input_data): try: # 工具的实际逻辑 result = process(input_data) return result except Exception as e: # 返回友好的错误信息，帮助Agent调整策略 return f&quot;工具执行失败：&#123;str(e)&#125;。建议：尝试其他方法或简化输入。&quot; 实践3：工具要有使用日志，记录工具调用的输入 / 输出 / 耗时，便于问题排查 1234567import loggingdef logged_tool(input_data): logging.info(f&quot;工具被调用，输入：&#123;input_data&#125;&quot;) result = execute(input_data) logging.info(f&quot;工具执行完成，输出：&#123;result&#125;&quot;) return result 4.Agent的工作原理与理解方式4.1 ReAct框架深度解析ReAct（Reasoning + Acting）是目前最主流的Agent工作框架，由Google Brain研究团队提出，核心是「思考 - 行动 - 观察」的循环闭环。 ReAct的核心循环暂时无法在飞书文档外展示此内容 完整的ReAct示例任务：「2024年哪个国家赢得了最多的奥运金牌？这个国家的首都是哪里？」 Agent的完整思考过程： 12345678910111213141516171819202122232425262728293031=== 第一轮循环 ===Thought 1:&quot;我需要找到2024年奥运会的金牌榜信息。这需要搜索最新的数据。&quot;Action 1:Tool: WebSearchInput: &quot;2024奥运会金牌榜&quot;Observation 1:&quot;2024年巴黎奥运会，美国队以40枚金牌位居榜首，中国队38枚金牌第二...&quot;=== 第二轮循环 ===Thought 2:&quot;好的，美国赢得了最多的金牌。现在我需要确认美国的首都。虽然我知道是华盛顿D.C.，但为了确保准确性，我应该验证一下。&quot;Action 2:Tool: WebSearchInput: &quot;美国首都&quot;Observation 2:&quot;美国的首都是华盛顿哥伦比亚特区（Washington, D.C.）...&quot;=== 完成 ===Thought 3:&quot;我已经获得了所有需要的信息，可以回答了。&quot;Final Answer:&quot;2024年巴黎奥运会，美国赢得了最多的金牌（40枚）。美国的首都是华盛顿哥伦比亚特区（Washington, D.C.）。&quot; ReAct的代码实现12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455565758596061626364from langchain.agents import create_react_agent, AgentExecutorfrom langchain_openai import ChatOpenAIfrom langchain.tools import Toolfrom langchain.prompts import PromptTemplate# 1. 定义ReAct的提示词模板react_prompt = PromptTemplate.from_template(&quot;&quot;&quot;你是一个AI助手，通过推理和行动来解决问题。可用工具：&#123;tools&#125;使用以下格式：Question: 需要回答的问题Thought: 你应该思考该做什么Action: 要采取的行动，必须是[&#123;tool_names&#125;]之一Action Input: 行动的输入Observation: 行动的结果... (这个Thought/Action/Action Input/Observation可以重复N次)Thought: 我现在知道最终答案了Final Answer: 原始问题的最终答案开始！Question: &#123;input&#125;Thought: &#123;agent_scratchpad&#125;&quot;&quot;&quot;)# 2. 创建工具def search(query): # 简化的搜索实现 if &quot;金牌&quot; in query: return &quot;2024年巴黎奥运会美国队40枚金牌第一&quot; elif &quot;首都&quot; in query: return &quot;美国首都是华盛顿D.C.&quot;search_tool = Tool( name=&quot;Search&quot;, func=search, description=&quot;搜索互联网信息&quot;)# 3. 创建Agentllm = ChatOpenAI(model=&quot;gpt-4&quot;, temperature=0)agent = create_react_agent( llm=llm, tools=[search_tool], prompt=react_prompt)agent_executor = AgentExecutor( agent=agent, tools=[search_tool], verbose=True, # 显示详细过程 max_iterations=5 # 最多5轮循环)# 4. 执行任务result = agent_executor.invoke(&#123; &quot;input&quot;: &quot;2024年哪个国家赢得了最多的奥运金牌？这个国家的首都是哪里？&quot;&#125;)print(result[&quot;output&quot;]) 4.2 其他Agent工作模式除了ReAct，还有其他几种重要的工作模式： 模式1：Chain of Thought (CoT) - 纯推理暂时无法在飞书文档外展示此内容 特点： 只有思考，没有行动，无工具调用 适合纯逻辑推理问题 优点是Token消耗少 示例： 12345678问题：&quot;如果一个房间有3只猫，每只猫前面有2只猫，那一共有多少只猫？&quot;CoT推理：思考1：题目说&quot;每只猫前面有2只猫&quot;思考2：这意味着猫排成一排思考3：但只有3只猫，所以是循环的或者交叉的排列思考4：实际上还是3只猫答案：3只猫 模式2：Plan-and-Execute - 先计划后执行暂时无法在飞书文档外展示此内容 特点： 先一次性规划，再按计划执行 可以并行执行任务 适合流程明确的复杂任务 代码示例： 12345678910111213141516171819202122#1. 规划阶段planner_prompt = &quot;&quot;&quot;将任务分解为子任务：任务：&#123;task&#125;请输出JSON格式的任务列表：[ &#123;&quot;id&quot;: 1, &quot;description&quot;: &quot;...&quot;, &quot;dependencies&quot;: []&#125;, &#123;&quot;id&quot;: 2, &quot;description&quot;: &quot;...&quot;, &quot;dependencies&quot;: [1]&#125;, ...]&quot;&quot;&quot;plan = llm.invoke(planner_prompt.format( task=&quot;分析竞争对手的产品策略&quot;))# 2. 执行阶段for task in plan: if all_dependencies_completed(task): result = execute_task(task) store_result(task.id, result) 模式3：Self-Ask - 自问自答暂时无法在飞书文档外展示此内容 示例： 12345678910111213主问题：&quot;iPhone 15的屏幕比iPhone 14大多少？&quot;Agent自问自答：Q1: &quot;iPhone 15的屏幕尺寸是多少？&quot;→ 搜索得到：6.1英寸Q2: &quot;iPhone 14的屏幕尺寸是多少？&quot;→ 搜索得到：6.1英寸Q3: &quot;6.1英寸 - 6.1英寸 = ?&quot;→ 计算得到：0英寸最终答案：&quot;iPhone 15和iPhone 14的屏幕尺寸相同，都是6.1英寸。&quot; 4.3 理解Agent的三种视角视角1：把 Agent 看作能自主完成任务的「员工」12345678你（老板）：「帮我准备明天的演讲PPT」Agent（员工）：理解需求（演讲主题、目标听众）搜索资料（行业数据、案例）设计大纲（结构规划）制作PPT（使用工具）审核优化（自我检查）交付成果（PPT文件） 这个视角帮助你： 设计Agent的职责范围 定义输入输出格式 考虑错误处理 视角2：把Agent看作「循环系统」123输入 → [感知 → 思考 → 决策 → 行动 → 观察] → 输出 ↑_______________________________| 反馈循环 这个视角帮助你： 优化循环次数 设置终止条件 调试中间过程 视角3：把Agent看作「大脑+工具」123456789101112大脑（LLM）： 理解语言 推理规划 生成文本↕ 通信工具箱： 搜索引擎 计算器 API接口 数据库 这个视角帮助你： 扩展Agent能力（添加新工具） 优化工具选择（描述要精确） 提升执行效率（工具要快） 5.构建Agent的五大难点与解决方案5.1 难点一：无限循环与任务卡死问题描述Agent可能陷入死循环： 1234567891011Thought: 我需要搜索信息Action: Search(&quot;2024 AI&quot;)Observation: [搜索结果]Thought: 我需要搜索更详细的信息Action: Search(&quot;2024 AI详细&quot;)Observation: [搜索结果]Thought: 我需要搜索更详细的信息Action: Search(&quot;2024 AI更详细&quot;)...（永远循环） 解决方案方案1：设置最大迭代次数 1234567agent_executor = AgentExecutor( agent=agent, tools=tools, max_iterations=10, # 最多执行10轮 max_execution_time=60, # 最多执行60秒 early_stopping_method=&quot;generate&quot; # 超时时生成答案) 方案2：优化提示词，明确终止条件 123456prompt = &quot;&quot;&quot;你必须在5步内完成任务。如果5步内无法完成，请给出&quot;基于现有信息的最佳答案&quot;。当前已经执行了&#123;iterations&#125;步。&quot;&quot;&quot; 方案3：实现智能终止判断 1234567891011def should_continue(agent_state): # 检查是否在重复相同的行动 last_3_actions = agent_state.history[-3:] if len(set(last_3_actions)) == 1: # 最后3个动作都相同 return False # 终止 # 检查是否进展缓慢 if agent_state.iterations &gt; 5 and not has_new_info(agent_state): return False return True 5.2 难点二：工具选择错误问题描述12345678Agent选择了错误的工具：任务：&quot;计算2024年有多少天&quot;错误选择：Action: WebSearch(&quot;2024年有多少天&quot;) ❌ 不需要搜索正确选择：Action: Calculator(&quot;365 if not is_leap_year(2024) else 366&quot;) ✅ 根本原因 工具描述不清晰 Prompt没有给出使用规则 LLM对任务理解有偏差 解决方案方案1：改进工具描述 12345678910111213141516171819202122232425❌ 不好的描述calculator_tool = Tool( name=&quot;Calculator&quot;, description=&quot;计算&quot;)# ✅ 好的描述calculator_tool = Tool( name=&quot;Calculator&quot;, description=&quot;&quot;&quot; 用于精确的数学计算。 适用场景： - 算术运算（加减乘除） - 数学函数（平方、开方、三角函数） - 逻辑判断（比较大小） 输入格式：Python数学表达式字符串 示例：&quot;2 + 2&quot;, &quot;sqrt(16)&quot;, &quot;2024 % 4 == 0&quot; 不适用场景： - 需要最新数据（用Search） - 需要上下文信息（用Memory） &quot;&quot;&quot;) 方案2：添加工具使用示例 12345678910111213prompt = &quot;&quot;&quot;工具使用示例：问题：&quot;今天的天气如何？&quot;正确：Action: WeatherAPI(&quot;北京&quot;)错误：Action: Calculator(&quot;天气&quot;) # 天气不是数学问题问题：&quot;2的100次方是多少？&quot;正确：Action: Calculator(&quot;2**100&quot;)错误：Action: Search(&quot;2的100次方&quot;) # 不需要搜索现在请处理：&#123;input&#125;&quot;&quot;&quot; 方案3：实现工具推荐系统 12345678910111213141516def recommend_tool(task_description, available_tools): &quot;&quot;&quot;根据任务描述推荐工具&quot;&quot;&quot; # 使用LLM分析任务 analysis = llm.invoke(f&quot;&quot;&quot; 任务：&#123;task_description&#125; 请分析这个任务需要： 1. 实时数据吗？→ 需要Search 2. 数学计算吗？→ 需要Calculator 3. 历史信息吗？→ 需要Memory 推荐工具（JSON格式）： &#123;&#123;&quot;recommended&quot;: [&quot;tool1&quot;, &quot;tool2&quot;], &quot;reason&quot;: &quot;...&quot;&#125;&#125; &quot;&quot;&quot;) return analysis.recommended 5.3 难点三：上下文窗口溢出问题描述长对话或复杂任务会导致： 1234567Prompt + 历史对话 + 工具描述 + 中间结果 = 超过Token限制GPT-4: 128K tokensClaude: 200K tokens一次复杂任务可能消耗50K+ tokens→ 超出限制或成本过高 解决方案方案1：智能压缩上下文 123456789101112from langchain.memory import ConversationSummaryBufferMemorymemory = ConversationSummaryBufferMemory( llm=llm, max_token_limit=4000, # 保留最近4000 tokens moving_summary_buffer=&quot;&quot;, # 旧的对话自动总结)# 效果：# 旧对话：&quot;用户询问了天气、新闻、股票...共20轮对话&quot;# ↓ 总结为# &quot;用户主要关心北京天气（晴）、今日新闻（AI发展）、股票（上涨）&quot; 方案2：分层记忆 123456789101112131415161718192021222324252627class HierarchicalMemory: def init(self): self.recent_memory = [] # 最近3轮，完整保留 self.mid_term_memory = [] # 中期10轮，保留关键信息 self.long_term_memory = vectorstore # 长期，向量检索 def add(self, message): self.recent_memory.append(message) if len(self.recent_memory) &gt; 3: # 移到中期记忆，提取关键信息 old_message = self.recent_memory.pop(0) key_info = extract_key_info(old_message) self.mid_term_memory.append(key_info) if len(self.mid_term_memory) &gt; 10: # 移到长期记忆，存入向量库 old_info = self.mid_term_memory.pop(0) self.long_term_memory.add_texts([old_info]) def get_context(self, query): # 组合三层记忆 recent = &quot;
&quot;.join(self.recent_memory) mid = &quot;
&quot;.join(self.mid_term_memory) relevant = self.long_term_memory.similarity_search(query, k=2) return f&quot;&#123;recent&#125;

