uot;&quot; 技巧2：Chain of Thought1234567891011121314#❌ 直接要求答案prompt = &quot;2024年哪个国家GDP最高？&quot;# ✅ 引导逐步思考prompt = &quot;&quot;&quot;请回答：2024年哪个国家GDP最高？请按以下步骤思考：1. 首先，我需要搜索2024年全球GDP排名2. 然后，找到排名第一的国家3. 最后，验证这个信息的可靠性现在开始：&quot;&quot;&quot; 技巧3：角色扮演12345678910111213#❌ 通用指令prompt = &quot;帮我写代码&quot;#✅ 明确角色prompt = &quot;&quot;&quot;你是一个资深的Python工程师，有10年开发经验。你的代码特点：清晰易读注重性能考虑边界情况包含完整的错误处理现在请帮我写一个函数...&quot;&quot;&quot; 9.2 工具调用优化优化1：工具描述标准化12345678910111213141516171819202122232425262728293031323334353637383940414243class ToolDescriptionTemplate: &quot;&quot;&quot;标准化的工具描述模板&quot;&quot;&quot; @staticmethod def create_description( purpose: str, input_format: str, output_format: str, use_cases: list, limitations: list, ): return f&quot;&quot;&quot;工具目的：&#123;purpose&#125;输入格式：&#123;input_format&#125;输出格式：&#123;output_format&#125;适用场景：&#123;chr(10).join(f&quot;- &#123;case&#125;&quot; for case in use_cases)&#125;不适用场景：&#123;chr(10).join(f&quot;- &#123;limit&#125;&quot; for limit in limitations)&#125;示例：输入：&quot;example_input&quot;输出：&quot;example_output&quot;&quot;&quot;&quot;使用search_tool_desc = ToolDescriptionTemplate.create_description( purpose=&quot;搜索互联网获取最新信息&quot;, input_format=&quot;字符串（搜索查询）&quot;, output_format=&quot;字符串（搜索结果摘要）&quot;, use_cases=[ &quot;需要最新数据（新闻、事件）&quot;, &quot;查找具体信息（人物、地点）&quot;, &quot;验证事实&quot;, ], limitations=[ &quot;不用于数学计算&quot;, &quot;不用于代码执行&quot;, &quot;不用于个人隐私信息&quot;, ],) 优化2：工具调用缓存123456789101112131415161718192021222324252627282930313233from functools import lru_cacheimport hashlibclass CachedToolExecutor: def init(self): self.cache = &#123;&#125; self.cache_hits = 0 self.cache_misses = 0 def execute(self, tool_name: str, tool_input: str): # 生成缓存key cache_key = hashlib.md5( f&quot;&#123;tool_name&#125;:&#123;tool_input&#125;&quot;.encode() ).hexdigest() # 检查缓存 if cache_key in self.cache: self.cache_hits += 1 print(f&quot;✅ Cache hit! (命中率: &#123;self.hit_rate:.2%&#125;)&quot;) return self.cache[cache_key] # 执行工具 self.cache_misses += 1 result = self._actual_execute(tool_name, tool_input) # 存入缓存 self.cache[cache_key] = result return result @property def hit_rate(self): total = self.cache_hits + self.cache_misses return self.cache_hits / total if total &gt; 0 else 0 9.3 成本优化策略策略1：智能Token管理123456789101112131415161718192021class TokenOptimizer: def __init__(self, max_tokens=4000): self.max_tokens = max_tokens def compress_context(self, messages: list) -&gt; list: &quot;&quot;&quot;压缩上下文&quot;&quot;&quot; total_tokens = sum(len(m[&quot;content&quot;].split()) for m in messages) if total_tokens &lt;= self.max_tokens: return messages # 保留最近的和最重要的 recent_messages = messages[-3:] # 最近3条 important_messages = self._extract_important(messages[:-3]) return important_messages + recent_messages def _extract_important(self, messages): &quot;&quot;&quot;提取重要消息&quot;&quot;&quot; # 使用关键词识别重要性 important_keywords = [&quot;重要&quot;, &quot;关键&quot;, &quot;必须&quot;, &quot;注意&quot;] important = [] for msg in messages: if any(kw in msg[&quot;content&quot;] for kw in important_keywords): important.append(msg) return important[:2] # 最多保留2条 策略2：批量处理123456789101112131415161718192021222324252627def batch_process_with_cost_tracking(tasks, batch_size=10): &quot;&quot;&quot;批量处理并跟踪成本&quot;&quot;&quot; results = [] total_cost = 0 for i in range(0, len(tasks), batch_size): batch = tasks[i:i+batch_size] # 批量处理 batch_prompt = create_batch_prompt(batch) response = llm.invoke(batch_prompt) # 计算成本 tokens_used = count_tokens(batch_prompt) + count_tokens(response.content) batch_cost = calculate_cost(tokens_used) total_cost += batch_cost print(f&quot;批次&#123;i//batch_size + 1&#125;: &#123;len(batch)&#125;个任务, 成本$&#123;batch_cost:.4f&#125;&quot;) # 解析结果 batch_results = parse_batch_response(response.content) results.extend(batch_results) print(f&quot;
总成本: $&#123;total_cost:.4f&#125;&quot;) print(f&quot;平均每任务: $&#123;total_cost/len(tasks):.4f&#125;&quot;) return results 9.4 可靠性增强技巧1：重试机制123456789101112131415161718192021222324252627282930313233import timefrom functools import wrapsdef retry_with_exponential_backoff( max_retries=3, initial_delay=1, exponential_base=2,): &quot;&quot;&quot;指数退避重试装饰器&quot;&quot;&quot; def decorator(func): @wraps(func) def wrapper(*args, **kwargs): delay = initial_delay for attempt in range(max_retries): try: return func(*args, **kwargs) except Exception as e: if attempt == max_retries - 1: raise print(f&quot;⚠️ 尝试&#123;attempt+1&#125;失败: &#123;e&#125;&quot;) print(f&quot;等待&#123;delay&#125;秒后重试...&quot;) time.sleep(delay) delay *= exponential_base return wrapper return decorator# 使用@retry_with_exponential_backoff(max_retries=3)def call_llm(prompt): return llm.invoke(prompt) 技巧2：健康检查12345678910111213141516171819202122232425262728293031323334353637383940414243444546class AgentHealthMonitor: def init(self): self.metrics = &#123; &quot;total_requests&quot;: 0, &quot;successful_requests&quot;: 0, &quot;failed_requests&quot;: 0, &quot;total_latency&quot;: 0, &#125; def record_request(self, success: bool, latency: float): self.metrics[&quot;total_requests&quot;] += 1 self.metrics[&quot;total_latency&quot;] += latency if success: self.metrics[&quot;successful_requests&quot;] += 1 else: self.metrics[&quot;failed_requests&quot;] += 1 def get_health_status(self): total = self.metrics[&quot;total_requests&quot;] if total == 0: return &quot;UNKNOWN&quot; success_rate = self.metrics[&quot;successful_requests&quot;] / total avg_latency = self.metrics[&quot;total_latency&quot;] / total if success_rate &gt;= 0.95 and avg_latency &lt; 2: return &quot;HEALTHY&quot; elif success_rate &gt;= 0.8: return &quot;DEGRADED&quot; else: return &quot;UNHEALTHY&quot; def get_report(self): total = self.metrics[&quot;total_requests&quot;] if total == 0: return &quot;暂无数据&quot; return f&quot;&quot;&quot;健康状态：&#123;self.get_health_status()&#125;统计信息：- 总请求数：&#123;total&#125;- 成功率：&#123;self.metrics[&quot;successful_requests&quot;]/total:.2%&#125;- 平均延迟：&#123;self.metrics[&quot;total_latency&quot;]/total:.2f&#125;秒&quot;&quot;&quot; 9.5 调试与监控调试技巧1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859606162636465666768class DebugAgent: def init(self, agent, debug_mode=True): self.agent = agent self.debug_mode = debug_mode self.execution_log = [] def execute(self, task): if self.debug_mode: print(&quot;
