&quot;) start_time = time.time() try: # 记录每一步 result = self._execute_with_logging(task) if self.debug_mode: self._print_execution_summary(time.time() - start_time) return result except Exception as e: if self.debug_mode: self._print_error_details(e) raise def _execute_with_logging(self, task): # 钩子：记录每次工具调用 original_tool_call = self.agent.tool_executor.call def logged_tool_call(tool_name, tool_input): self.execution_log.append(&#123; &quot;type&quot;: &quot;tool_call&quot;, &quot;tool&quot;: tool_name, &quot;input&quot;: tool_input, &quot;timestamp&quot;: time.time(), &#125;) result = original_tool_call(tool_name, tool_input) self.execution_log.append(&#123; &quot;type&quot;: &quot;tool_result&quot;, &quot;tool&quot;: tool_name, &quot;result&quot;: result, &quot;timestamp&quot;: time.time(), &#125;) if self.debug_mode: print(f&quot;
🔧 工具调用：&#123;tool_name&#125;&quot;) print(f&quot;输入：&#123;tool_input&#125;&quot;) print(f&quot;输出：&#123;result[:100]&#125;...&quot;) return result self.agent.tool_executor.call = logged_tool_call return self.agent.execute(task) def _print_execution_summary(self, duration): print(&quot;
&quot; + &quot;=&quot;*50) print(&quot;📊 执行总结&quot;) print(&quot;=&quot;*50) print(f&quot;总耗时：&#123;duration:.2f&#125;秒&quot;) print(f&quot;工具调用次数：&#123;len([l for l in self.execution_log if l[&#x27;type&#x27;]==&#x27;tool_call&#x27;])&#125;&quot;) print(f&quot;执行步骤：&#123;len(self.execution_log)&#125;&quot;) 10.未来展望：Agent的发展趋势10.1 技术趋势趋势1：更强的推理能力12345678当前（2024）：GPT-4：擅长语言理解和生成推理能力有限（复杂数学、逻辑）未来（2025-2026）：OpenAI o1系列：专注推理DeepSeek-R1：强化学习推理推理时间↑，推理准确度↑ 影响： Agent可以处理更复杂的任务 减少对外部工具的依赖 更少的错误和幻觉 趋势2：多模态Agent123456当前：主要处理文本未来：图像理解（识别图表、设计UI）视频分析（剪辑、内容审核）语音交互（实时对话）3D环境操作（游戏、仿真） 示例场景： 1用户上传设计草图 → Agent识别 → 生成HTML/CSS → 自动部署网站 趋势3：个性化和记忆增强12345当前：对话级记忆未来：跨会话的长期记忆个性化学习（理解用户习惯）主动建议（不等用户询问） 补充 🎯 第一章：什么是意图识别？一个生活化的例子1.1 从咖啡店点单说起想象你走进一家咖啡店，对服务员说：”好冷啊，来点热的。” 服务员会怎么做？她不会傻乎乎地问”你到底要什么”，而是立刻明白： 表面话语：”好冷啊，来点热的” 真实意图：我想要一杯热饮 这就是意图识别！ 1.2 AI Agent中的意图识别 在AI世界里，意图识别（Intent Recognition）就是让机器理解用户说话背后的真实目的。 举个例子： 用户说的话 AI识别的意图 应该做什么 “今天天气怎么样？” 查询天气 调用天气API “帮我订张去北京的机票” 预订机票 打开订票流程 “我的订单到哪了？” 查询订单 查询物流信息 “太贵了，有便宜点的吗？” 价格筛选 推荐低价商品 配图说明：参见 intent_recognition_flow.svg 1.3 为什么意图识别这么重要？没有意图识别的AI就像： 🤖 只会死板回答的机器人 ❌ 听不懂人话的客服 😵 需要你说精确命令的语音助手 有了意图识别的AI就像： ✨ 能读懂你心思的贴心助手 💡 聪明的问题解决专家 🎯 精准响应的智能系统 🧠 第二章：AI Agent的”读心术”：意图识别的魔法原理2.1 意图识别的三层结构意图识别不是一步到位的，而是分为三个层次： 第一层：文本理解（Text Understanding）把用户说的话变成机器能理解的形式。 例子： 123456789用户输入：&quot;我想买一台笔记本电脑，预算5000左右&quot;↓ 文本理解结构化数据：&#123; &quot;动作&quot;: &quot;购买&quot;, &quot;商品类别&quot;: &quot;笔记本电脑&quot;, &quot;预算&quot;: 5000, &quot;单位&quot;: &quot;元&quot;&#125; 第二层：意图分类（Intent Classification）判断用户想做什么事情。 例子： 12345678输入：&quot;这款手机有货吗？&quot;→ 意图分类 → 库存查询输入：&quot;帮我退货&quot;→ 意图分类 → 退款申请输入：&quot;客服在吗？&quot;→ 意图分类 → 人工服务 第三层：槽位填充（Slot Filling）提取关键信息，填补意图执行所需的参数。 例子： 12345678910111213意图：预订酒店必需槽位： - 城市：？ - 入住日期：？ - 退房日期：？ - 房间数量：？用户说：&quot;下周去上海住两晚&quot;提取结果： - 城市：上海 ✓ - 入住日期：下周一 ✓ - 退房日期：下周三 ✓ - 房间数量：未知 ✗ → 需要追问 2.2 意图识别的工作流程配图说明：参见 workflow.svg 完整流程如下： 1231. 用户输入 → 2. 文本预处理 → 3. 特征提取 → 4. 意图分类 ↓7. 执行动作 ← 6. 槽位验证 ← 5. 槽位填充 ← [意图+槽位] 具体步骤解释： 用户输入：接收原始文本 文本预处理：去除标点、统一大小写、分词 特征提取：将文本转为向量（数字表示） 意图分类：用模型预测意图类别 槽位填充：提取关键信息 槽位验证：检查必需信息是否完整 执行动作：调用对应的功能模块 🔬 第三章：三大核心技术：让AI懂你所想3.1 技术一：基于规则的意图识别（规则匹配）原理用预定义的关键词和模式来匹配用户意图。 优点 ✅ 简单易懂 ✅ 可控性强 ✅ 适合固定场景 缺点 ❌ 覆盖面窄 ❌ 难以处理复杂语句 ❌ 维护成本高 代码示例1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950class RuleBasedIntentRecognizer: def __init__(self): # 定义意图规则字典 self.intent_rules = &#123; &quot;查询天气&quot;: [&quot;天气&quot;, &quot;温度&quot;, &quot;下雨&quot;, &quot;晴天&quot;, &quot;气温&quot;], &quot;订票&quot;: [&quot;订票&quot;, &quot;买票&quot;, &quot;机票&quot;, &quot;车票&quot;, &quot;预订&quot;], &quot;查询订单&quot;: [&quot;订单&quot;, &quot;物流&quot;, &quot;快递&quot;, &quot;到哪了&quot;, &quot;发货&quot;], &quot;退款&quot;: [&quot;退款&quot;, &quot;退货&quot;, &quot;不想要&quot;, &quot;退钱&quot;], &quot;人工客服&quot;: [&quot;人工&quot;, &quot;客服&quot;, &quot;转人工&quot;, &quot;找客服&quot;] &#125; def recognize(self, text): &quot;&quot;&quot;识别意图&quot;&quot;&quot; text = text.lower() # 转小写 # 遍历所有意图规则 for intent, keywords in self.intent_rules.items(): # 检查是否包含关键词 for keyword in keywords: if keyword in text: return &#123; &quot;intent&quot;: intent, &quot;confidence&quot;: 0.9, # 规则匹配给固定置信度 &quot;matched_keyword&quot;: keyword &#125; # 没有匹配到任何规则 return &#123; &quot;intent&quot;: &quot;未知意图&quot;, &quot;confidence&quot;: 0.0, &quot;matched_keyword&quot;: None &#125;# 使用示例recognizer = RuleBasedIntentRecognizer()# 测试test_cases = [ &quot;今天天气怎么样？&quot;, &quot;帮我订张机票&quot;, &quot;我的快递到哪了？&quot;, &quot;想退货&quot;, &quot;转人工客服&quot;]for text in test_cases: result = recognizer.recognize(text) print(f&quot;输入: &#123;text&#125;&quot;) print(f&quot;意图: &#123;result[&#x27;intent&#x27;]&#125;, 置信度: &#123;result[&#x27;confidence&#x27;]&#125;&quot;) print() 运行结果： 1234567891011121314输入: 今天天气怎么样？意图: 查询天气, 置信度: 0.9输入: 帮我订张机票意图: 订票, 置信度: 0.9输入: 我的快递到哪了？意图: 查询订单, 置信度: 0.9输入: 想退货意图: 退款, 置信度: 0.9输入: 转人工客服意图: 人工客服, 置信度: 0.9 3.2 技术二：基于机器学习的意图识别原理用大量标注数据训练分类模型，让AI自动学习意图识别规律。 核心步骤 数据准备 1234567891011# 训练数据示例training_data = [ (&quot;今天天气怎么样&quot;, &quot;查询天气&quot;), (&quot;北京现在多少度&quot;, &quot;查询天气&quot;), (&quot;会下雨吗&quot;, &quot;查询天气&quot;), (&quot;帮我订一张机票&quot;, &quot;订票&quot;), (&quot;买票去上海&quot;, &quot;订票&quot;), (&quot;预订高铁票&quot;, &quot;订票&quot;), (&quot;我的订单到哪了&quot;, &quot;查询订单&quot;), (&quot;快递什么时候到&quot;, &quot;查询订单&quot;),] 特征工程 将文本转为向量： 12345678910from sklearn.feature_extraction.text import TfidfVectorizer# TF-IDF向量化vectorizer = TfidfVectorizer()X = vectorizer.fit_transform([text for text, _ in training_data])# 文本 &quot;今天天气怎么样&quot; 会变成向量：# [0.0, 0.5, 0.3, 0.0, 0.7, ...]# ↑ ↑ ↑ ↑ ↑# 词1 词2 词3 词4 词5 模型训练 12345from sklearn.naive_bayes import MultinomialNB# 朴素贝叶斯分类器classifier = MultinomialNB()classifier.fit(X, labels) 完整代码实现12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455565758596061626364656667686970717273747576777879808182import jiebafrom sklearn.feature_extraction.text import TfidfVectorizerfrom sklearn.naive_bayes import MultinomialNBfrom sklearn.model_selection import train_test_splitimport numpy as npclass MLIntentRecognizer: def __init__(self): self.vectorizer = TfidfVectorizer( tokenizer=lambda x: jieba.lcut(x), # 中文分词 max_features=1000 ) self.classifier = MultinomialNB() self.is_trained = False def train(self, texts, labels): &quot;&quot;&quot;训练模型&quot;&quot;&quot; # 特征提取 X = self.vectorizer.fit_transform(texts) # 训练分类器 self.classifier.fit(X, labels) self.is_trained = True print(&quot;✅ 模型训练完成！&quot;) def predict(self, text): &quot;&quot;&quot;预测意图&quot;&quot;&quot; if not self.is_trained: return &#123;&quot;error&quot;: &quot;模型未训练&quot;&#125; # 特征提取 X = self.vectorizer.transform([text]) # 预测意图 intent = self.classifier.predict(X)[0] # 获取置信度 probas = self.classifier.predict_proba(X)[0] confidence = float(np.max(probas)) return &#123; &quot;intent&quot;: intent, &quot;confidence&quot;: confidence &#125;# 准备训练数据texts = [ &quot;今天天气怎么样&quot;, &quot;北京现在多少度&quot;, &quot;会下雨吗&quot;, &quot;明天晴天吗&quot;, &quot;帮我订一张机票&quot;, &quot;买票去上海&quot;, &quot;预订高铁票&quot;, &quot;购买火车票&quot;, &quot;我的订单到哪了&quot;, &quot;快递什么时候到&quot;, &quot;查询物流&quot;, &quot;包裹在哪&quot;, &quot;我要退款&quot;, &quot;申请退货&quot;, &quot;不想要了&quot;, &quot;退钱&quot;, &quot;转人工客服&quot;, &quot;找客服&quot;, &quot;人工服务&quot;, &quot;联系客服&quot;]labels = [ &quot;查询天气&quot;, &quot;查询天气&quot;, &quot;查询天气&quot;, &quot;查询天气&quot;, &quot;订票&quot;, &quot;订票&quot;, &quot;订票&quot;, &quot;订票&quot;, &quot;查询订单&quot;, &quot;查询订单&quot;, &quot;查询订单&quot;, &quot;查询订单&quot;, &quot;退款&quot;, &quot;退款&quot;, &quot;退款&quot;, &quot;退款&quot;, &quot;人工客服&quot;, &quot;人工客服&quot;, &quot;人工客服&quot;, &quot;人工客服&quot;]# 训练模型recognizer = MLIntentRecognizer()recognizer.train(texts, labels)# 测试test_cases = [ &quot;今天会不会下雨&quot;, &quot;我想买张去广州的票&quot;, &quot;订单什么时候能到&quot;, &quot;能退货吗&quot;, &quot;我要找人工&quot;]print(&quot;
📊 测试结果：
&quot;)for text in test_cases: result = recognizer.predict(text) print(f&quot;输入: &#123;text&#125;&quot;) print(f&quot;意图: &#123;result[&#x27;intent&#x27;]&#125;, 置信度: &#123;result[&#x27;confidence&#x27;]:.2f&#125;&quot;) print() 3.3 技术三：基于深度学习的意图识别（BERT）原理使用预训练语言模型（如BERT），理解上下文语义。 BERT的优势 ✅ 理解上下文 ✅ 处理复杂语句 ✅ 泛化能力强 ✅ 准确率高 代码实现123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990919293949596979899100101102103104105106from transformers import BertTokenizer, BertForSequenceClassificationimport torchimport torch.nn.functional as Fclass BERTIntentRecognizer: def __init__(self, model_name=&#x27;bert-base-chinese&#x27;): &quot;&quot;&quot;初始化BERT模型&quot;&quot;&quot; self.tokenizer = BertTokenizer.from_pretrained(model_name) self.model = None self.intent_labels = [] def prepare_data(self, texts, labels): &quot;&quot;&quot;准备训练数据&quot;&quot;&quot; # 获取唯一的标签 self.intent_labels = list(set(labels)) # 将标签转为数字 label_to_id = &#123;label: i for i, label in enumerate(self.intent_labels)&#125; numeric_labels = [label_to_id[label] for label in labels] # 分词和编码 encodings = self.tokenizer( texts, padding=True, truncation=True, max_length=128, return_tensors=&#x27;pt&#x27; ) return encodings, torch.tensor(numeric_labels) def train(self, texts, labels, epochs=3): &quot;&quot;&quot;训练BERT模型&quot;&quot;&quot; print(&quot;🚀 开始训练BERT模型...&quot;) # 准备数据 encodings, numeric_labels = self.prepare_data(texts, labels) # 初始化模型 num_labels = len(self.intent_labels) self.model = BertForSequenceClassification.from_pretrained( &#x27;bert-base-chinese&#x27;, num_labels=num_labels ) # 优化器 optimizer = torch.optim.AdamW(self.model.parameters(), lr=2e-5) # 训练循环 self.model.train() for epoch in range(epochs): optimizer.zero_grad() outputs = self.model( input_ids=encodings[&#x27;input_ids&#x27;], attention_mask=encodings[&#x27;attention_mask&#x27;], labels=numeric_labels ) loss = outputs.loss loss.backward() optimizer.step() print(f&quot;Epoch &#123;epoch+1&#125;/&#123;epochs&#125;, Loss: &#123;loss.item():.4f&#125;&quot;) print(&quot;✅ BERT模型训练完成！&quot;) def predict(self, text): &quot;&quot;&quot;预测意图&quot;&quot;&quot; if self.model is None: return &#123;&quot;error&quot;: &quot;模型未训练&quot;&#125; # 编码输入 encoding = self.tokenizer( text, padding=True, truncation=True, max_length=128, return_tensors=&#x27;pt&#x27; ) # 预测 self.model.eval() with torch.no_grad(): outputs = self.model( input_ids=encoding[&#x27;input_ids&#x27;], attention_mask=encoding[&#x27;attention_mask&#x27;] ) # 获取概率分布 probas = F.softmax(outputs.logits, dim=1) confidence, pred_idx = torch.max(probas, dim=1) intent = self.intent_labels[pred_idx.item()] return &#123; &quot;intent&quot;: intent, &quot;confidence&quot;: float(confidence.item()), &quot;all_probabilities&quot;: &#123; self.intent_labels[i]: float(probas[0][i]) for i in range(len(self.intent_labels)) &#125; &#125;# 使用示例# 注意：需要先安装 transformers: pip install transformers torch 🛠️ 第四章：从零开始：手把手搭建意图识别系统4.1 系统架构设计 我们将构建一个完整的意图识别系统，包含： 文本预处理模块 意图识别引擎 槽位提取模块 对话管理器 4.2 第一步：文本预处理123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354import reimport jiebaclass TextPreprocessor: &quot;&quot;&quot;文本预处理器&quot;&quot;&quot; def __init__(self): # 加载停用词 self.stopwords = set([&#x27;的&#x27;, &#x27;了&#x27;, &#x27;在&#x27;, &#x27;是&#x27;, &#x27;我&#x27;, &#x27;有&#x27;, &#x27;和&#x27;, &#x27;就&#x27;, &#x27;不&#x27;, &#x27;人&#x27;, &#x27;都&#x27;, &#x27;一&#x27;, &#x27;一个&#x27;, &#x27;上&#x27;, &#x27;也&#x27;, &#x27;很&#x27;]) def clean_text(self, text): &quot;&quot;&quot;清洗文本&quot;&quot;&quot; # 1. 去除特殊字符 text = re.sub(r&#x27;[^\w\s]&#x27;, &#x27;&#x27;, text) # 2. 去除多余空格 text = &#x27; &#x27;.join(text.split()) # 3. 转小写（对英文） text = text.lower() return text def tokenize(self, text): &quot;&quot;&quot;分词&quot;&quot;&quot; return jieba.lcut(text) def remove_stopwords(self, tokens): &quot;&quot;&quot;去除停用词&quot;&quot;&quot; return [token for token in tokens if token not in self.stopwords] def preprocess(self, text): &quot;&quot;&quot;完整预处理流程&quot;&quot;&quot; # 清洗 text = self.clean_text(text) # 分词 tokens = self.tokenize(text) # 去停用词 tokens = self.remove_stopwords(tokens) return &#123; &quot;original&quot;: text, &quot;tokens&quot;: tokens, &quot;processed&quot;: &#x27; &#x27;.join(tokens) &#125;# 测试preprocessor = TextPreprocessor()result = preprocessor.preprocess(&quot;今天的天气怎么样啊？？&quot;)print(result)# 输出: &#123;&#x27;original&#x27;: &#x27;今天天气怎么样啊&#x27;, &#x27;tokens&#x27;: [&#x27;今天&#x27;, &#x27;天气&#x27;, &#x27;怎么样&#x27;, &#x27;啊&#x27;], ...&#125; 4.3 第二步：槽位提取123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990919293949596979899100101102103104105106107108import refrom datetime import datetime, timedeltaclass SlotExtractor: &quot;&quot;&quot;槽位提取器&quot;&quot;&quot; def __init__(self): # 定义槽位模式 self.patterns = &#123; &quot;城市&quot;: r&#x27;(北京|上海|广州|深圳|杭州|成都|武汉|西安)&#x27;, &quot;日期&quot;: r&#x27;(今天|明天|后天|下周|周\w)&#x27;, &quot;数量&quot;: r&#x27;(\d+)\s*(个|张|份|次)&#x27;, &quot;价格&quot;: r&#x27;(\d+)\s*(元|块|rmb)&#x27;, &#125; def extract_slots(self, text, intent): &quot;&quot;&quot;根据意图提取槽位&quot;&quot;&quot; slots = &#123;&#125; # 根据不同意图提取不同槽位 if intent == &quot;查询天气&quot;: slots = self._extract_weather_slots(text) elif intent == &quot;订票&quot;: slots = self._extract_booking_slots(text) elif intent == &quot;查询订单&quot;: slots = self._extract_order_slots(text) return slots def _extract_weather_slots(self, text): &quot;&quot;&quot;提取天气查询槽位&quot;&quot;&quot; slots = &#123;&#125; # 提取城市 city_match = re.search(self.patterns[&quot;城市&quot;], text) if city_match: slots[&quot;city&quot;] = city_match.group(1) # 提取日期 date_match = re.search(self.patterns[&quot;日期&quot;], text) if date_match: slots[&quot;date&quot;] = self._parse_date(date_match.group(1)) else: slots[&quot;date&quot;] = &quot;今天&quot; return slots def _extract_booking_slots(self, text): &quot;&quot;&quot;提取订票槽位&quot;&quot;&quot; slots = &#123;&#125; # 提取出发地和目的地 cities = re.findall(self.patterns[&quot;城市&quot;], text) if len(cities) &gt;= 2: slots[&quot;from&quot;] = cities[0] slots[&quot;to&quot;] = cities[1] elif len(cities) == 1: slots[&quot;to&quot;] = cities[0] # 提取日期 date_match = re.search(self.patterns[&quot;日期&quot;], text) if date_match: slots[&quot;date&quot;] = self._parse_date(date_match.group(1)) # 提取数量 qty_match = re.search(self.patterns[&quot;数量&quot;], text) if qty_match: slots[&quot;quantity&quot;] = int(qty_match.group(1)) return slots def _extract_order_slots(self, text): &quot;&quot;&quot;提取订单查询槽位&quot;&quot;&quot; slots = &#123;&#125; # 提取订单号（示例） order_pattern = r&#x27;([A-Z0-9]&#123;10,&#125;)&#x27; order_match = re.search(order_pattern, text) if order_match: slots[&quot;order_id&quot;] = order_match.group(1) return slots def _parse_date(self, date_str): &quot;&quot;&quot;解析日期字符串&quot;&quot;&quot; today = datetime.now() if date_str == &quot;今天&quot;: return today.strftime(&quot;%Y-%m-%d&quot;) elif date_str == &quot;明天&quot;: return (today + timedelta(days=1)).strftime(&quot;%Y-%m-%d&quot;) elif date_str == &quot;后天&quot;: return (today + timedelta(days=2)).strftime(&quot;%Y-%m-%d&quot;) else: return date_str# 测试extractor = SlotExtractor()# 测试天气查询slots = extractor.extract_slots(&quot;明天北京天气怎么样&quot;, &quot;查询天气&quot;)print(&quot;天气槽位:&quot;, slots)# 输出: &#123;&#x27;city&#x27;: &#x27;北京&#x27;, &#x27;date&#x27;: &#x27;2024-xx-xx&#x27;&#125;# 测试订票slots = extractor.extract_slots(&quot;订2张从上海到北京的票&quot;, &quot;订票&quot;)print(&quot;订票槽位:&quot;, slots)# 输出: &#123;&#x27;from&#x27;: &#x27;上海&#x27;, &#x27;to&#x27;: &#x27;北京&#x27;, &#x27;quantity&#x27;: 2&#125; 4.4 第三步：完整意图识别引擎123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566676869707172737475767778798081828384858687888990919293949596979899100101102103104105106107class IntentRecognitionEngine: &quot;&quot;&quot;完整的意图识别引擎&quot;&quot;&quot; def __init__(self): self.preprocessor = TextPreprocessor() self.intent_recognizer = MLIntentRecognizer() # 可替换为BERT self.slot_extractor = SlotExtractor() # 意图置信度阈值 self.confidence_threshold = 0.6 def process(self, text): &quot;&quot;&quot;处理用户输入&quot;&quot;&quot; # 1. 文本预处理 preprocessed = self.preprocessor.preprocess(text) # 2. 意图识别 intent_result = self.intent_recognizer.predict(text) # 3. 检查置信度 if intent_result[&#x27;confidence&#x27;] &lt; self.confidence_threshold: return &#123; &quot;status&quot;: &quot;uncertain&quot;, &quot;message&quot;: &quot;抱歉，我没太理解您的意思，能换个说法吗？&quot;, &quot;confidence&quot;: intent_result[&#x27;confidence&#x27;] &#125; # 4. 槽位提取 slots = self.slot_extractor.extract_slots( text, intent_result[&#x27;intent&#x27;] ) # 5. 验证必需槽位 missing_slots = self._check_required_slots( intent_result[&#x27;intent&#x27;], slots ) if missing_slots: return &#123; &quot;status&quot;: &quot;incomplete&quot;, &quot;intent&quot;: intent_result[&#x27;intent&#x27;], &quot;slots&quot;: slots, &quot;missing_slots&quot;: missing_slots, &quot;message&quot;: self._generate_slot_question(missing_slots[0]) &#125; # 6. 返回完整结果 return &#123; &quot;status&quot;: &quot;complete&quot;, &quot;intent&quot;: intent_result[&#x27;intent&#x27;], &quot;confidence&quot;: intent_result[&#x27;confidence&#x27;], &quot;slots&quot;: slots, &quot;preprocessed&quot;: preprocessed &#125; def _check_required_slots(self, intent, slots): &quot;&quot;&quot;检查必需槽位&quot;&quot;&quot; required_slots = &#123; &quot;查询天气&quot;: [&quot;city&quot;], &quot;订票&quot;: [&quot;to&quot;, &quot;date&quot;], &quot;查询订单&quot;: [], &#125; required = required_slots.get(intent, []) missing = [slot for slot in required if slot not in slots] return missing def _generate_slot_question(self, slot_name): &quot;&quot;&quot;生成槽位询问语句&quot;&quot;&quot; questions = &#123; &quot;city&quot;: &quot;请问您想查询哪个城市的天气？&quot;, &quot;to&quot;: &quot;请问您