in parts if p.strip()] def recognize(self, text): &quot;&quot;&quot;识别多意图&quot;&quot;&quot; # 拆分句子 parts = self.split_sentence(text) # 识别每个部分的意图 results = [] for i, part in enumerate(parts): result = self.single_recognizer.process(part) result[&#x27;sequence&#x27;] = i + 1 results.append(result) return &#123; &quot;has_multiple_intents&quot;: len(results) &gt; 1, &quot;intents&quot;: results &#125;# 测试multi_recognizer = MultiIntentRecognizer()text = &quot;帮我查明天北京天气，然后订张去上海的票&quot;result = multi_recognizer.recognize(text)print(&quot;多意图识别结果:&quot;)for intent in result[&#x27;intents&#x27;]: print(f&quot; 意图&#123;intent[&#x27;sequence&#x27;]&#125;: &#123;intent[&#x27;intent&#x27;]&#125;&quot;) 6.3 置信度校准123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566class ConfidenceCalibrator: &quot;&quot;&quot;置信度校准器&quot;&quot;&quot; def __init__(self): self.thresholds = &#123; &quot;high&quot;: 0.85, # 高置信度 &quot;medium&quot;: 0.6, # 中等置信度 &quot;low&quot;: 0.3 # 低置信度 &#125; def calibrate(self, intent, confidence): &quot;&quot;&quot;校准置信度&quot;&quot;&quot; if confidence &gt;= self.thresholds[&quot;high&quot;]: return &#123; &quot;intent&quot;: intent, &quot;confidence&quot;: confidence, &quot;level&quot;: &quot;high&quot;, &quot;action&quot;: &quot;直接执行&quot;, &quot;message&quot;: None &#125; elif confidence &gt;= self.thresholds[&quot;medium&quot;]: return &#123; &quot;intent&quot;: intent, &quot;confidence&quot;: confidence, &quot;level&quot;: &quot;medium&quot;, &quot;action&quot;: &quot;二次确认&quot;, &quot;message&quot;: f&quot;您是想&#123;intent&#125;吗？&quot; &#125; elif confidence &gt;= self.thresholds[&quot;low&quot;]: return &#123; &quot;intent&quot;: intent, &quot;confidence&quot;: confidence, &quot;level&quot;: &quot;low&quot;, &quot;action&quot;: &quot;提供选项&quot;, &quot;message&quot;: f&quot;您可能想：
