在限制内 if len(self.history) &gt; self.max_history: self.history = self.history[-self.max_history:] def get_context(self): &quot;&quot;&quot;获取当前上下文&quot;&quot;&quot; return self.context def get_last_intent(self): &quot;&quot;&quot;获取上一轮意图&quot;&quot;&quot; if self.history: return self.history[-1][&quot;intent&quot;] return None 7.2 性能优化建议优化1：模型缓存1234567891011121314151617181920212223242526import pickleclass ModelCache: &quot;&quot;&quot;模型缓存&quot;&quot;&quot; @staticmethod def save_model(model, filename): &quot;&quot;&quot;保存模型&quot;&quot;&quot; with open(filename, &#x27;wb&#x27;) as f: pickle.dump(model, f) print(f&quot;✅ 模型已保存到 &#123;filename&#125;&quot;) @staticmethod def load_model(filename): &quot;&quot;&quot;加载模型&quot;&quot;&quot; with open(filename, &#x27;rb&#x27;) as f: model = pickle.load(f) print(f&quot;✅ 模型已从 &#123;filename&#125; 加载&quot;) return model# 使用# 训练后保存ModelCache.save_model(recognizer, &quot;intent_model.pkl&quot;)# 下次直接加载recognizer = ModelCache.load_model(&quot;intent_model.pkl&quot;) 优化2：批量处理12345678910def batch_predict(recognizer, texts, batch_size=32): &quot;&quot;&quot;批量预测&quot;&quot;&quot; results = [] for i in range(0, len(texts), batch_size): batch = texts[i:i+batch_size] batch_results = [recognizer.predict(text) for text in batch] results.extend(batch_results) return results 7.3 评估指标123456789101112131415161718from sklearn.metrics import classification_report, confusion_matrixdef evaluate_model(recognizer, test_texts, test_labels): &quot;&quot;&quot;评估模型性能&quot;&quot;&quot; predictions = [recognizer.predict(text)[&#x27;intent&#x27;] for text in test_texts] # 分类报告 print(&quot;📊 分类报告:&quot;) print(classification_report(test_labels, predictions)) # 混淆矩阵 print(&quot;
