in parts if p.strip()] def recognize(self, text): &quot;&quot;&quot;识别多意图&quot;&quot;&quot; # 拆分句子 parts = self.split_sentence(text) # 识别每个部分的意图 results = [] for i, part in enumerate(parts): result = self.single_recognizer.process(part) result[&#x27;sequence&#x27;] = i + 1 results.append(result) return &#123; &quot;has_multiple_intents&quot;: len(results) &gt; 1, &quot;intents&quot;: results &#125;# 测试multi_recognizer = MultiIntentRecognizer()text = &quot;帮我查明天北京天气，然后订张去上海的票&quot;result = multi_recognizer.recognize(text)print(&quot;多意图识别结果:&quot;)for intent in result[&#x27;intents&#x27;]: print(f&quot; 意图&#123;intent[&#x27;sequence&#x27;]&#125;: &#123;intent[&#x27;intent&#x27;]&#125;&quot;) 6.3 置信度校准123456789101112131415161718192021222324252627282930313233343536373839404142434445464748495051525354555657585960616263646566class ConfidenceCalibrator: &quot;&quot;&quot;置信度校准器&quot;&quot;&quot; def __init__(self): self.thresholds = &#123; &quot;high&quot;: 0.85, # 高置信度 &quot;medium&quot;: 0.6, # 中等置信度 &quot;low&quot;: 0.3 # 低置信度 &#125; def calibrate(self, intent, confidence): &quot;&quot;&quot;校准置信度&quot;&quot;&quot; if confidence &gt;= self.thresholds[&quot;high&quot;]: return &#123; &quot;intent&quot;: intent, &quot;confidence&quot;: confidence, &quot;level&quot;: &quot;high&quot;, &quot;action&quot;: &quot;直接执行&quot;, &quot;message&quot;: None &#125; elif confidence &gt;= self.thresholds[&quot;medium&quot;]: return &#123; &quot;intent&quot;: intent, &quot;confidence&quot;: confidence, &quot;level&quot;: &quot;medium&quot;, &quot;action&quot;: &quot;二次确认&quot;, &quot;message&quot;: f&quot;您是想&#123;intent&#125;吗？&quot; &#125; elif confidence &gt;= self.thresholds[&quot;low&quot;]: return &#123; &quot;intent&quot;: intent, &quot;confidence&quot;: confidence, &quot;level&quot;: &quot;low&quot;, &quot;action&quot;: &quot;提供选项&quot;, &quot;message&quot;: f&quot;您可能想：
1. &#123;intent&#125;
2. 其他...
请选择&quot; &#125; else: return &#123; &quot;intent&quot;: &quot;未知&quot;, &quot;confidence&quot;: confidence, &quot;level&quot;: &quot;very_low&quot;, &quot;action&quot;: &quot;拒绝识别&quot;, &quot;message&quot;: &quot;抱歉，我没太理解，能换个说法吗？&quot; &#125;# 使用示例calibrator = ConfidenceCalibrator()# 测试不同置信度test_cases = [ (&quot;查询天气&quot;, 0.95), (&quot;订票&quot;, 0.7), (&quot;退款&quot;, 0.4), (&quot;未知意图&quot;, 0.1)]for intent, conf in test_cases: result = calibrator.calibrate(intent, conf) print(f&quot;意图: &#123;intent&#125;, 置信度: &#123;conf&#125;&quot;) print(f&quot;处理方式: &#123;result[&#x27;action&#x27;]&#125;&quot;) if result[&#x27;message&#x27;]: print(f&quot;消息: &#123;result[&#x27;message&#x27;]&#125;&quot;) print() 🔍 第七章：常见问题与优化策略7.1 常见问题汇总问题1：识别准确率低原因： 训练数据不足 意图分类过于模糊 缺少上下文信息 解决方案： 1234567891011121314151617181920212223# 1. 数据增强def augment_data(text): &quot;&quot;&quot;数据增强&quot;&quot;&quot; variations = [] # 同义词替换 synonyms = &#123; &quot;查询&quot;: [&quot;查看&quot;, &quot;看看&quot;, &quot;了解&quot;], &quot;订票&quot;: [&quot;买票&quot;, &quot;购买&quot;, &quot;预订&quot;], &#125; for original, syns in synonyms.items(): if original in text: for syn in syns: variations.append(text.replace(original, syn)) return variations# 2. 增加训练样本original_data = [&quot;查询天气&quot;]augmented_data = augment_data(original_data[0])print(augmented_data)# [&#x27;查看天气&#x27;, &#x27;看看天气&#x27;, &#x27;了解天气&#x27;] 问题2：多轮对话记忆丢失解决方案： 123456789101112131415161718192021222324252627282930313233343536class ConversationMemory: &quot;&quot;&quot;对话记忆管理器&quot;&quot;&quot; def __init__(self, max_history=10): self.history = [] self.max_history = max_history self.context = &#123;&#125; def add_turn(self, user_input, bot_response, intent, slots): &quot;&quot;&quot;添加对话轮次&quot;&quot;&quot; turn = &#123; &quot;user&quot;: user_input, &quot;bot&quot;: bot_response, &quot;intent&quot;: intent, &quot;slots&quot;: slots, &quot;timestamp&quot;: datetime.now() &#125; self.history.append(turn) # 更新上下文 self.context.update(slots) # 保持历史记录在限制内 if len(self.history) &gt; self.max_history: self.history = self.history[-self.max_history:] def get_context(self): &quot;&quot;&quot;获取当前上下文&quot;&quot;&quot; return self.context def get_last_intent(self): &quot;&quot;&quot;获取上一轮意图&quot;&quot;&quot; if self.history: return self.history[-1][&quot;intent&quot;] return None 7.2 性能优化建议优化1：模型缓存1234567891011121314151617181920212223242526import pickleclass ModelCache: &quot;&quot;&quot;模型缓存&quot;&quot;&quot; @staticmethod def save_model(model, filename): &quot;&quot;&quot;保存模型&quot;&quot;&quot; with open(filename, &#x27;wb&#x27;) as f: pickle.dump(model, f) print(f&quot;✅ 模型已保存到 &#123;filename&#125;&quot;) @staticmethod def load_model(filename): &quot;&quot;&quot;加载模型&quot;&quot;&quot; with open(filename, &#x27;rb&#x27;) as f: model = pickle.load(f) print(f&quot;✅ 模型已从 &#123;filename&#125; 加载&quot;) return model# 使用# 训练后保存ModelCache.save_model(recognizer, &quot;intent_model.pkl&quot;)# 下次直接加载recognizer = ModelCache.load_model(&quot;intent_model.pkl&quot;) 优化2：批量处理12345678910def batch_predict(recognizer, texts, batch_size=32): &quot;&quot;&quot;批量预测&quot;&quot;&quot; results = [] for i in range(0, len(texts), batch_size): batch = texts[i:i+batch_size] batch_results = [recognizer.predict(text) for text in batch] results.extend(batch_results) return results 7.3 评估指标123456789101112131415161718from sklearn.metrics import classification_report, confusion_matrixdef evaluate_model(recognizer, test_texts, test_labels): &quot;&quot;&quot;评估模型性能&quot;&quot;&quot; predictions = [recognizer.predict(text)[&#x27;intent&#x27;] for text in test_texts] # 分类报告 print(&quot;📊 分类报告:&quot;) print(classification_report(test_labels, predictions)) # 混淆矩阵 print(&quot;
📊 混淆矩阵:&quot;) print(confusion_matrix(test_labels, predictions)) # 准确率 accuracy = sum(p == l for p, l in zip(predictions, test_labels)) / len(test_labels) print(f&quot;
✅ 总体准确率: &#123;accuracy:.2%&#125;&quot;)

AI开发基础：Langchain框架从入门到实战开发-附代码 LangChain 实战教程：从入门到实战 一份接地气的 LangChain 学习指南，带你从零开始构建 AI 应用 写在前面这份教程不会堆砌概念，我会用最直白的话告诉你 LangChain 是什么、怎么用。代码都是能跑的，直接抄就行。 适合学AI应用开发，或者后端转AI开发的想快速上手的同学。 适合谁看： 听说过 ChatGPT，想自己做点 AI 应用的开发者 被官方文档绕晕的同学 想快速上手实战项目的人 1. LangChain 是什么？一句话解释LangChain = 让大模型能”动手干活”的框架 光靠 ChatGPT 只能聊天，但通过 LangChain，你可以让 AI： 查天气、搜网页 读文件、写代码 调用你公司的内部 API 自己决定该做什么 架构图 核心能力 能力 说明 举个例子 模型抽象 一套代码适配多个大模型 今天用 GPT-4，明天换 Claude，代码不用改 工具调用 让 AI 能调用外部功能 AI 可以帮你查股票、发邮件、操作数据库 记忆管理 让 AI 记住对话历史 多轮对话不会”失忆” Agent 让 AI 自主决策 给它一个目标，它自己规划怎么完成 2. 环境搭建安装依赖12345678910111213141516# 创建虚拟环境（推荐）python -m venv langchain_envsource langchain_env/bin/activate # Mac/Linux# langchain_env\Scripts\activate # Windows# 安装 LangChain 核心包pip install langchain langchain-core langchain-community# 根据你用的模型安装对应包pip install langchain-openai # OpenAIpip install langchain-anthropic # Claudepip install dashscope # 通义千问# 其他常用包pip install python-dotenv # 环境变量管理pip install langgraph # Agent 运行时（新版必装） 配置 API Key创建 .env 文件： 12345678# OpenAIOPENAI_API_KEY=sk-xxx# 或者通义千问DASHSCOPE_API_KEY=sk-xxx# ClaudeANTHROPIC_API_KEY=sk-xxx 验证安装123456789101112131415from dotenv import load_dotenvimport osload_dotenv()# 通义千问示例from langchain_community.chat_models import ChatTongyillm = ChatTongyi( model=&quot;qwen-turbo&quot;, dashscope_api_key=os.getenv(&quot;DASHSCOPE_API_KEY&quot;))response = llm.invoke(&quot;你好，请用一句话介绍自己&quot;)print(response.content) 跑通了就说明环境 OK！ 3. 核心概念速览LangChain 的核心就四个东西，搞懂了就入门了： 概念地图 四大核心 概念 是什么 类比 Model 大语言模型 大脑 Prompt 提示词模板 问题格式 Tool 外部工具 双手 Agent 智能代理 管家，帮你协调一切 关系是这样的： 1用户提问 → Prompt 格式化 → Agent 思考 → 调用 Tool → Model 生成回答 → 返回用户 4. Prompt 提示词模板提示词模板就是把”问问题”这件事标准化。不用每次都手写完整的提示词。 工作流程 4.1 最简单的模板1234567891011from langchain_core.prompts import PromptTemplate# 定义模板，用 &#123;&#125; 占位template = PromptTemplate.from_template( &quot;请用&#123;language&#125;语言介绍一下&#123;topic&#125;，不超过100字。&quot;)# 填充变量prompt = template.format(language=&quot;中文&quot;, topic=&quot;人工智能&quot;)print(prompt)# 输出: 请用中文语言介绍一下人工智能，不超过100字。 4.2 聊天模板（常用）做聊天应用一般用这个，可以设置 system 和 user 角色： 1234567891011121314151617from langchain_core.prompts import ChatPromptTemplate# 定义多轮对话模板chat_template = ChatPromptTemplate.from_messages([ (&quot;system&quot;, &quot;你是一位&#123;role&#125;，擅长用简洁易懂的方式解释复杂概念。&quot;), (&quot;human&quot;, &quot;请解释一下：&#123;concept&#125;&quot;),])# 生成消息列表messages = chat_template.format_messages( role=&quot;物理学教授&quot;, concept=&quot;量子纠缠&quot;)# 调用模型response = llm.invoke(messages)print(response.content) 4.3 Few-shot 示例模板通过给几个例子，教 AI 按你想要的格式输出： 123456789101112131415# 定义示例examples = [ &#123;&quot;input&quot;: &quot;开心&quot;, &quot;output&quot;: &quot;我今天非常开心！&quot;&#125;, &#123;&quot;input&quot;: &quot;难过&quot;, &quot;output&quot;: &quot;我感到有些难过...&quot;&#125;,]# 创建包含示例的模板few_shot_template = ChatPromptTemplate.from_messages([ (&quot;system&quot;, &quot;你是一个情绪表达助手。&quot;), (&quot;human&quot;, &quot;示例：
情绪: 开心
表达: 我今天非常开心！

情绪: 难过
表达: 我感到有些难过...&quot;), (&quot;human&quot;, &quot;现在请表达这个情绪: &#123;emotion&#125;&quot;)])messages = few_shot_template.format_messages(emotion=&quot;兴奋&quot;)response = llm.invoke(messages) 4.4 动态日期模板有些变量想自动填充（比如当前日期）： 12345678910111213from datetime import datetimefrom langchain_core.prompts import PromptTemplatetemplate = PromptTemplate( template=&quot;今天是&#123;date&#125;，请告诉我关于&#123;topic&#125;的最新消息。&quot;, input_variables=[&quot;topic&quot;], partial_variables=&#123; &quot;date&quot;: datetime.now().strftime(&quot;%Y年%m月%d日&quot;) # 自动填充 &#125;)# 只需要传 topicprompt = template.format(topic=&quot;AI发展&quot;) 5. Tools 工具定义工具就是让 AI 能调用的函数。定义好工具后，AI 会自己决定什么时候用、怎么用。 5.1 用装饰器定义（最简单）123456789101112131415161718192021222324252627from langchain_core.tools import tool@tooldef get_weather(city: str) -&gt; str: &quot;&quot;&quot; 获取城市的天气信息 Args: city: 城市名称，如&quot;北京&quot;、&quot;上海&quot; &quot;&quot;&quot; # 模拟天气数据（实际项目中调用天气 API） weather_data = &#123; &quot;北京&quot;: &quot;晴天，25°C&quot;, &quot;上海&quot;: &quot;多云，22°C&quot;, &quot;深圳&quot;: &quot;小雨，28°C&quot;, &#125; return weather_data.get(city, f&quot;&#123;city&#125;的天气暂时无法获取&quot;)# 测试工具result = get_weather.invoke(&#123;&quot;city&quot;: &quot;北京&quot;&#125;)print(result) # 输出: 晴天，25°C# 查看工具信息print(f&quot;工具名称: &#123;get_weather.name&#125;&quot;)print(f&quot;工具描述: &#123;get_weather.description&#125;&quot;)print(f&quot;参数结构: &#123;get_weather.args&#125;&quot;) 重点：docstring 写清楚！ AI 就是靠这个描述来决定什么时候调用这个工具。 5.2 更复杂的工具123456789101112131415161718192021222324252627282930313233from typing import Optional@tooldef search_database(query: str, category: Optional[str] = None) -&gt; str: &quot;&quot;&quot; 在数据库中搜索信息 Args: query: 搜索关键词 category: 可选的分类过滤器，如&quot;科技&quot;、&quot;健康&quot;、&quot;教育&quot; &quot;&quot;&quot; database = &#123; &quot;科技&quot;: [&quot;人工智能正在改变世界&quot;, &quot;5G技术的应用&quot;], &quot;健康&quot;: [&quot;健康饮食的重要性&quot;, &quot;运动与长寿的关系&quot;], &quot;教育&quot;: [&quot;在线学习的趋势&quot;, &quot;终身学习的价值&quot;] &#125; results = [] if category and category in database: for item in database[category]: if query.lower() in item.lower(): results.append(f&quot;[&#123;category&#125;] &#123;item&#125;&quot;) else: for cat, items in database.items(): for item in items: if query.lower() in item.lower(): results.append(f&quot;[&#123;cat&#125;] &#123;item&#125;&quot;) if results: return &quot;找到以下结果:
&quot; + &quot;
&quot;.join(results) else: return f&quot;没有找到关于 &#x27;&#123;query&#125;&#x27; 的结果&quot; 5.3 用类定义（需要更多控制时）1234567891011121314151617181920212223242526272829from langchain_core.tools import BaseToolfrom pydantic import BaseModel, Fieldfrom typing import Type# 定义输入参数结构class CalculatorInput(BaseModel): expression: str = Field(description=&quot;数学表达式，如 &#x27;2+2&#x27; 或 &#x27;10*5&#x27;&quot;)class Calculator(BaseTool): name: str = &quot;calculator&quot; description: str = &quot;执行数学计算&quot; args_schema: Type[BaseModel] = CalculatorInput def _run(self, expression: str) -&gt; str: &quot;&quot;&quot;同步执行&quot;&quot;&quot; try: result = eval(expression) return f&quot;计算结果: &#123;expression&#125; = &#123;result&#125;&quot; except Exception as e: return f&quot;计算错误: &#123;str(e)&#125;&quot; async def _arun(self, expression: str) -&gt; str: &quot;&quot;&quot;异步执行（可选实现）&quot;&quot;&quot; return self._run(expression)# 使用calc = Calculator()result = calc.invoke(&#123;&quot;expression&quot;: &quot;123 * 456&quot;&#125;)print(result) # 计算结果: 123 * 456 = 56088 5.4 把工具绑定到模型定义好工具后，需要”告诉”模型这些工具的存在： 1234567891011121314# 创建工具列表tools = [get_weather, search_database, Calculator()]# 绑定到模型llm_with_tools = llm.bind_tools(tools)# 现在模型知道有这些工具可用了response = llm_with_tools.invoke(&quot;北京今天天气如何？&quot;)# 检查模型是否决定调用工具if response.tool_calls: for tool_call in response.tool_calls: print(f&quot;模型想调用: &#123;tool_call[&#x27;name&#x27;]&#125;&quot;) print(f&quot;传入参数: &#123;tool_call[&#x27;args&#x27;]&#125;&quot;) 6. Agent 智能代理Agent 是 LangChain 最酷的部分。它不是按固定流程执行，而是自己思考、自己决定该干啥。 Agent 思考循环 6.1 LangChain 1.0+ 新版 Agent新版用 create_agent，底层基于 LangGraph，更稳定： 1234567891011121314151617181920212223242526272829303132333435363738394041424344454647484950515253545556575859from langchain.agents import create_agentfrom langchain_core.tools import toolfrom langchain_community.chat_models import ChatTongyiimport os# 1. 初始化模型llm = ChatTongyi( model=&quot;qwen-plus&quot;, temperature=0.7, dashscope_api_key=os.environ.get(&quot;DASHSCOPE_API_KEY&quot;))# 2. 定义工具@tooldef get_weather(city: str) -&gt; str: &quot;&quot;&quot;获取城市天气信息&quot;&quot;&quot; weather_db = &#123; &quot;北京&quot;: &quot;晴天，15-25度&quot;, &quot;上海&quot;: &quot;多云，18-28度&quot;, &quot;深圳&quot;: &quot;小雨，20-30度&quot;, &#125; return weather_db.get(city, f&quot;&#123;city&#125;的天气信息暂不可用&quot;)@tooldef calculator(expression: str) -&gt; str: &quot;&quot;&quot;执行数学计算&quot;&quot;&quot; try: result = eval(expression) return f&quot;计算结果: &#123;expression&#125; = &#123;result&#125;&quot; except: return &quot;计算错误&quot;@tool def search_knowledge(query: str) -&gt; str: &quot;&quot;&quot;搜索知识库&quot;&quot;&quot; knowledge = &#123; &quot;LangChain&quot;: &quot;LangChain是一个用于开发LLM应用的框架，支持工具、代理、内存管理等功能。&quot;, &quot;机器学习&quot;: &quot;机器学习是AI的子集，让系统能从数据中自动学习和改进。&quot;, &#125; for key, value in knowledge.items(): if key in query: return value return f&quot;未找到关于&#x27;&#123;query&#125;&#x27;的信息&quot;# 3. 创建 Agentagent = create_agent( model=llm, tools=[get_weather, calculator, search_knowledge], system_prompt=&quot;你是一个专业的中文助手。仔细分析用户问题，选择合适的工具来回答。&quot;)# 4. 使用 Agentresult = agent.invoke(&#123; &quot;messages&quot;: [&#123;&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: &quot;北京今天天气怎么样？&quot;&#125;]&#125;)# 获取回答final_message = result[&quot;messages&quot;][-1]print(f&quot;回答: &#123;final_message.content&#125;&quot;) 6.2 Agent 处理多个问题123456789101112131415test_queries = [ &quot;北京今天天气怎么样？&quot;, &quot;给我讲讲什么是机器学习&quot;, &quot;计算 123 * 456&quot;,]for query in test_queries: print(f&quot;
用户: &#123;query&#125;&quot;) result = agent.invoke(&#123; &quot;messages&quot;: [&#123;&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: query&#125;] &#125;) final_message = result[&quot;messages&quot;][-1] print(f&quot;助手: &#123;final_message.content&#125;&quot;) 6.3 带记忆的 Agent让 Agent 记住对话历史： 1234567891011121314151617181920212223242526272829from langgraph.checkpoint.memory import MemorySaver# 创建记忆存储checkpointer = MemorySaver()# 创建带记忆的 Agentagent = create_agent( model=llm, tools=[get_weather, calculator, search_knowledge], system_prompt=&quot;你是一个专业助手，能记住之前的对话。&quot;, checkpointer=checkpointer # 启用记忆)# 会话配置（同一个 thread_id 共享记忆）config = &#123;&quot;configurable&quot;: &#123;&quot;thread_id&quot;: &quot;session_001&quot;&#125;&#125;# 第一轮对话result1 = agent.invoke( &#123;&quot;messages&quot;: [&#123;&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: &quot;我叫小明&quot;&#125;]&#125;, config)print(result1[&quot;messages&quot;][-1].content)# 第二轮对话（Agent 会记得用户叫小明）result2 = agent.invoke( &#123;&quot;messages&quot;: [&#123;&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: &quot;我叫什么名字？&quot;&#125;]&#125;, config)print(result2[&quot;messages&quot;][-1].content) # 会回答&quot;小明&quot; 6.4 流式输出让回答一个字一个字输出，体验更好： 123456789101112# 流式调用for chunk in agent.stream( &#123;&quot;messages&quot;: [&#123;&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: &quot;北京天气如何？&quot;&#125;]&#125;, config, stream_mode=&quot;values&quot;): messages = chunk.get(&quot;messages&quot;) if messages: last_message = messages[-1] if hasattr(last_message, &quot;content&quot;) and last_message.content: print(last_message.content, end=&quot;&quot;, flush=True)print() # 换行 7. 完整项目：全能智能助手现在把前面学的串起来，做一个能干实事的智能助手。 7.1 项目结构12345678910smart_assistant&#x2F;├── .env # API Key├── main.py # 主程序├── tools&#x2F; # 工具定义│ ├── __init__.py│ ├── weather.py│ ├── calculator.py│ ├── translator.py│ └── knowledge.py└── requirements.txt 7.2 工具定义tools/weather.py 12345678910111213141516171819202122232425262728293031from langchain_core.tools import toolfrom datetime import datetime@tooldef get_weather(city: str) -&gt; str: &quot;&quot;&quot; 获取指定城市的实时天气信息 Args: city: 城市名称，支持北京、上海、广州、深圳、杭州等 &quot;&quot;&quot; weather_database = &#123; &quot;北京&quot;: &#123;&quot;condition&quot;: &quot;晴天&quot;, &quot;temp&quot;: &quot;15-25°C&quot;, &quot;aqi&quot;: &quot;优&quot;&#125;, &quot;上海&quot;: &#123;&quot;condition&quot;: &quot;多云&quot;, &quot;temp&quot;: &quot;18-28°C&quot;, &quot;aqi&quot;: &quot;良&quot;&#125;, &quot;深圳&quot;: &#123;&quot;condition&quot;: &quot;小雨&quot;, &quot;temp&quot;: &quot;22-30°C&quot;, &quot;aqi&quot;: &quot;优&quot;&#125;, &quot;杭州&quot;: &#123;&quot;condition&quot;: &quot;阴天&quot;, &quot;temp&quot;: &quot;17-26°C&quot;, &quot;aqi&quot;: &quot;良&quot;&#125;, &quot;广州&quot;: &#123;&quot;condition&quot;: &quot;晴天&quot;, &quot;temp&quot;: &quot;20-32°C&quot;, &quot;aqi&quot;: &quot;良&quot;&#125;, &#125; if city not in weather_database: return f&quot;暂无&#123;city&#125;的天气数据，支持城市：北京、上海、深圳、杭州、广州&quot; data = weather_database[city] return f&quot;&quot;&quot;&#123;city&#125; 天气预报━━━━━━━━━━━━━━━━天气：&#123;data[&#x27;condition&#x27;]&#125;温度：&#123;data[&#x27;temp&#x27;]&#125;空气质量：&#123;data[&#x27;aqi&#x27;]&#125;更新时间：&#123;datetime.now().strftime(&quot;%H:%M&quot;)&#125; &quot;&quot;&quot;.strip() tools/calculator.py 1234567891011121314151617181920212223242526from langchain_core.tools import tool@tooldef calculator(expression: str) -&gt; str: &quot;&quot;&quot; 执行数学计算 Args: expression: 数学表达式，如 &quot;2+2&quot;、&quot;(10*5)+20&quot;、&quot;2**8&quot; &quot;&quot;&quot; try: # 安全检查 allowed_chars = set(&#x27;0123456789+-*/(). &#x27;) if not all(c in allowed_chars for c in expression.replace(&#x27;**&#x27;, &#x27;&#x27;)): return &quot;表达式包含非法字符&quot; result = eval(expression, &#123;&quot;__builtins__&quot;: &#123;&#125;&#125;, &#123;&#125;) if isinstance(result, float) and result.is_integer(): result = int(result) return f&quot;计算结果：&#123;expression&#125; = &#123;result&#125;&quot; except ZeroDivisionError: return &quot;错误：除数不能为零&quot; except Exception as e: return f&quot;计算错误：&#123;str(e)&#125;&quot; tools/translator.py 12345678910111213141516171819202122from langchain_core.tools import tool@tooldef translate(text: str, target_language: str = &quot;英文&quot;) -&gt; str: &quot;&quot;&quot; 将中文文本翻译成其他语言（模拟） Args: text: 要翻译的中文文本 target_language: 目标语言，支持&quot;英文&quot;、&quot;日文&quot;、&quot;韩文&quot; &quot;&quot;&quot; translations = &#123; &quot;你好&quot;: &#123;&quot;英文&quot;: &quot;Hello&quot;, &quot;日文&quot;: &quot;こんにちは&quot;, &quot;韩文&quot;: &quot;안녕하세요&quot;&#125;, &quot;谢谢&quot;: &#123;&quot;英文&quot;: &quot;Thank you&quot;, &quot;日文&quot;: &quot;ありがとう&quot;, &quot;韩文&quot;: &quot;감사합니다&quot;&#125;, &quot;再见&quot;: &#123;&quot;英文&quot;: &quot;Goodbye&quot;, &quot;日文&quot;: &quot;さようなら&quot;, &quot;韩文&quot;: &quot;안녕히 가세요&quot;&#125;, &#125; if text in translations and target_language in translations[text]: result = translations[text][target_language] return f&quot;翻译结果：&#x27;&#123;text&#125;&#x27; → [&#123;target_language&#125;] &#123;result&#125;&quot; return f&quot;暂不支持&#x27;&#123;text&#125;&#x27;的&#123;target_language&#125;翻译&quot; 7.3 主程序main.py 12345678910111213141516171819202122232425262728293031323334353637383940414243444546474849505152535455565758596061626364656667686970717273747576777879808182838485import osfrom dotenv import load_dotenvfrom langchain.agents import create_agentfrom langchain_community.chat_models import ChatTongyifrom langgraph.checkpoint.memory import MemorySaver# 导入工具from tools.weather import get_weatherfrom tools.calculator import calculatorfrom tools.translator import translate# 加载环境变量load_dotenv()# 系统提示词SYSTEM_PROMPT = &quot;&quot;&quot;你是小智，一个全能智能助手。你可以帮用户：• 查询天气：查询中国主要城市的天气• 数学计算：进行各种数学运算• 文本翻译：将中文翻译成其他语言工作原则：1. 先理解用户意图，选择合适的工具2. 如果不确定，可以询问用户3. 回答简洁明了，有帮助&quot;&quot;&quot;def create_assistant(): &quot;&quot;&quot;创建智能助手&quot;&quot;&quot; # 初始化模型 llm = ChatTongyi( model=&quot;qwen-plus&quot;, temperature=0.7, dashscope_api_key=os.environ.get(&quot;DASHSCOPE_API_KEY&quot;) ) # 创建记忆 checkpointer = MemorySaver() # 创建 Agent agent = create_agent( model=llm, tools=[get_weather, calculator, translate], system_prompt=SYSTEM_PROMPT, checkpointer=checkpointer ) return agentdef main(): &quot;&quot;&quot;主函数&quot;&quot;&quot; print(&quot;=&quot; * 50) print(&quot; 小智 - 全能智能助手 v1.0&quot;) print(&quot;=&quot; * 50) print(&quot;输入 &#x27;quit&#x27; 退出
&quot;) agent = create_assistant() config = &#123;&quot;configurable&quot;: &#123;&quot;thread_id&quot;: &quot;main&quot;&#125;&#125; while True: user_input = input(&quot;你: &quot;).strip() if user_input.lower() in [&#x27;quit&#x27;, &#x27;退出&#x27;, &#x27;exit&#x27;]: print(&quot;再见！&quot;) break if not user_input: continue try: result = agent.invoke( &#123;&quot;messages&quot;: [&#123;&quot;role&quot;: &quot;user&quot;, &quot;content&quot;: user_input&#125;]&#125;, config ) response = result[&quot;messages&quot;][-1].content print(f&quot;小智: &#123;response&#125;
&quot;) except Exception as e: print(f&quot;出错了: &#123;str(e)&#125;
&quot;)if __name__ == &quot;__main__&quot;: main() 7.4 运行效果12345678910111213141516171819202122&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D; 小智 - 全能智能助手 v1.0&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;&#x3D;输入 &#39;quit&#39; 退出你: 北京天气怎么样小智: 北京 天气预报━━━━━━━━━━━━━━━━天气：晴天温度：15-25°C空气质量：优更新时间：14:30你: 帮我算一下 125 * 88小智: 计算结果：125 * 88 &#x3D; 11000你: 把&quot;你好&quot;翻译成日文小智: 翻译结果：&#39;你好&#39; → [日文] こんにちは你: quit再见！ 8. 进阶技巧与最佳实践8.1 工具描述要写好AI 完全靠工具的 description 来决定什么时候调用。写得不清楚，它就不会用。 坏例子： 1234@tooldef func(x: str) -&gt; str: &quot;&quot;&quot;处理数据&quot;&quot;&quot; # 太模糊了！ pass 好例子： 1234567891011121314@tooldef get_stock_price(symbol: str) -&gt; str: &quot;&quot;&quot; 获取股票实时价格 当用户询问某只股票的价格、涨跌情况时使用此工具。 Args: symbol: 股票代码，如 &quot;AAPL&quot;（苹果）、&quot;GOOGL&quot;（谷歌） Returns: 包含当前价格、涨跌幅的字符串 &quot;&quot;&quot; pass 8.2 错误处理要完善工具可能会失败（网络错误、参数错误等），一定要有兜底： 12345678910111213@tooldef fetch_data(url: str) -&gt; str: &quot;&quot;&quot;从URL获取数据&quot;&quot;&quot; try: response = requests.get(url, timeout=10) response.raise_for_status() return response.text except requests.Timeout: return &quot;请求超时，请稍后重试&quot; except requests.RequestException as e: return f&quot;请求失败：&#123;str(e)&#125;&quot; except Exception as e: return f&quot;未知错误：&#123;str(e)&#125;&quot; 8.3 调整温度参数 temperature=0：输出最确定，适合事实查询 temperature=0.7：有一定创意，适合对话 temperature=1.0：输出多样，适合创作 8.4 使用 LangSmith 调试遇到奇怪问题时，用 LangSmith 看看 Agent 到底在想什么： 12345import os# 在代码最前面添加os.environ[&quot;LANGCHAIN_TRACING_V2&quot;] = &quot;true&quot;os.environ[&quot;LANGCHAIN_API_KEY&quot;] = &quot;你的LangSmith API Key&quot; 然后去 smith.langchain.com 就能看到每一步的详细 trace。 8.5 控制迭代次数防止 Agent 陷入死循环： 123456789101112agent = create_agent( model=llm, tools=tools, # 其他选项)# 调用时限制最大步数result = agent.invoke( &#123;&quot;messages&quot;: [...]&#125;, config, recursion_limit=10 # 最多10步)
